/**
 * Pure template helpers for the creator-outreach-plus-invite email (round 3,
 * 2026-09-30 — see scripts/creator-outreach-invite-send.ts's header for the
 * full history). Factored out of that script so a backfill/audit tool can
 * import buildEmail()/firstNameOf() without any top-level CLI arg parsing or
 * process.exit() side effects running on import.
 */
export const SUBJECT_TMPL = "{{fullName}} × Nxeon — Sponsorship Offer";
/** No longer attached (2026-10-01) — a PDF on a cold first-contact email is a
 *  real spam-filter trigger; linked instead, hosted at TERMS_URL below. */
export const TERMS_URL = "https://nxeon.cloud/creator-partner-terms.pdf";

const INTRO_MD = `Hey {{firstName}},

I'm Santino, founder of Nxeon, a Canadian cloud hosting company focused on game servers, VPS hosting, and developer infrastructure.

Nxeon supports 50+ different game titles, with {{game}} being one of our most popular. With 13 data centers across 4 continents, we're able to provide fast, reliable service to your viewers around the globe. We also offer 24/7 support and have built a community-driven mod library with 70,000+ mods and over 11.5 billion total downloads.

We've been steadily growing Nxeon and are now launching our creator partner program. I came across your content around {{game}} and really like what you're building, so I wanted to reach out and see if you'd be interested in working together.

For the launch of our creator program, we're offering a highly competitive founding partner offer that we don't expect to keep at this level permanently. We want to give the creators who join us early the strongest possible opportunity to benefit as Nxeon continues to grow.

Here's what we'd like to offer:`;

const OFFER_ITEMS = [
  "40% lifetime recurring commission on customers you refer",
  "50% off their first month for your audience",
  "10% off every month after through your personal creator code",
  "Your own Nxeon Partner Portal to track referrals, customers, renewals, commissions, and payouts",
  "Monthly commission payouts at the beginning of each month",
  "Your own referral link and creator code",
  "Promotional assets and direct support from our team",
];

const MID_MD = `The 40% commission is lifetime, meaning you continue earning for as long as the customers you refer remain with Nxeon. If they purchase additional services in the future, you can earn from those as well.

This launch offer is specifically designed for our early creator partners. As the program grows, we expect future partnership terms to become more standardized, so joining during the launch gives you access to the most generous version of our creator program.

We're looking to build genuine, long-term relationships with creators rather than simply doing one-off sponsorships. As Nxeon continues to grow, we want our creators to grow alongside us.`;

const INVITE_MD = `I've gone ahead and put together a Creator Partner invite for you so you can see exactly how it works. Claiming it isn't a commitment — you can look around, stop anytime, or not even start at all. Once you're in, you pick your own creator code and see everything live inside the portal. If you'd like to test things out first, just let me know and we'll apply a free server to the partner account we create for you, so you can try it yourself before deciding on anything.

You can read our full Creator Partner terms here: {{termsUrl}}`;

const OUTRO_MD = `If you have any questions before or after you take a look, you can either reply here, or message me on WhatsApp for a faster response and direct support.`;

export function firstNameOf(fullName: string): string {
  return fullName.trim().split(/\s+/)[0] || fullName.trim();
}
function fill(tmpl: string, vars: Record<string, string>): string {
  return tmpl.replace(/\{\{(\w+)\}\}/g, (_, k) => vars[k] ?? "");
}
function mdParagraphsToHtml(md: string): string {
  return md
    .split(/\n{2,}/)
    .map((p) => `<p style="margin:0 0 14px;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.6;color:#222;">${p.split("\n").join("<br>")}</p>`)
    .join("\n");
}
function offerListHtml(items: string[]): string {
  const lis = items.map((it) => `<li style="margin:0 0 6px;">${it}</li>`).join("\n");
  return `<ul style="margin:0 0 14px;padding-left:22px;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.6;color:#222;">\n${lis}\n</ul>`;
}
function offerListText(items: string[]): string {
  return items.map((it) => `- ${it}`).join("\n");
}
function ctaButtonHtml(href: string, label: string): string {
  return `<div style="margin:22px 0;"><a href="${href}" style="display:inline-block;background:#5b3df0;color:#fff;text-decoration:none;font-family:Arial,Helvetica,sans-serif;font-size:15px;font-weight:bold;padding:12px 22px;border-radius:8px;">${label}</a></div>`;
}

export function buildEmail(vars: { fullName: string; firstName: string; game: string }, claimUrl: string) {
  const fillVars = { ...vars, termsUrl: TERMS_URL };
  const subject = fill(SUBJECT_TMPL, fillVars);
  const introMd = fill(INTRO_MD, fillVars);
  const inviteMd = fill(INVITE_MD, fillVars);
  const html = [
    mdParagraphsToHtml(introMd),
    offerListHtml(OFFER_ITEMS),
    mdParagraphsToHtml(MID_MD),
    mdParagraphsToHtml(inviteMd),
    ctaButtonHtml(claimUrl, "Claim Your Partner Invite"),
    mdParagraphsToHtml(OUTRO_MD),
  ].join("\n");
  const text = [introMd, offerListText(OFFER_ITEMS), MID_MD, inviteMd, `Claim your invite: ${claimUrl}`, OUTRO_MD].join("\n\n");
  return { subject, html, text };
}
/**
 * Shared single-recipient send logic for the creator-outreach template
 * (lib/creator-outreach-template.ts) — extracted from
 * scripts/creator-outreach-invite-send.ts so the throttled worker queue
 * (worker/index.ts's processOutreachQueueTick, draining OutreachQueueItem one
 * row per minute) and that CLI script send the IDENTICAL email through the
 * IDENTICAL path, rather than two copies that can drift apart.
 */
import { randomBytes } from "node:crypto";
import nodemailer from "nodemailer";
import { db } from "./db";
import { decryptSecret } from "./crypto-box";
import { mailTlsOptions, withImap } from "./mail/imap";
import { MAIL_SMTP_HOST, MAIL_SMTP_PORT } from "./mail/types";
import { buildEmail, firstNameOf } from "./creator-outreach-template";
import { recordEmail } from "./email-render";
import {
  createCreatorDrafts,
  hashInviteToken,
  creatorClaimUrl,
  CREATOR_INVITE_TTL_DAYS,
} from "./partner-invite-core";

const FROM_ADDRESS = "santino@nxeon.cloud";

/** Finds the account's real Sent folder name (IMAP servers vary: "Sent", "INBOX.Sent", "Sent Items"...). */
async function findSentPath(client: { list(): Promise<Array<{ path: string; specialUse?: string }>> }): Promise<string> {
  const boxes = await client.list();
  const byFlag = boxes.find((b) => b.specialUse === "\\Sent");
  if (byFlag) return byFlag.path;
  const byName = boxes.find((b) => /sent/i.test(b.path));
  return byName?.path ?? "Sent";
}

export type OutreachMailerContext = {
  displayName: string;
  password: string;
  signatureHtml: string;
  signatureText: string;
  footerHtml: string;
  footerText: string;
  smtp: nodemailer.Transporter;
};

/** Resolve the sending mailbox + brand footer ONCE — reused across many sends
 *  (one script run, or many worker ticks) rather than re-querying every time. */
export async function loadOutreachMailerContext(): Promise<OutreachMailerContext> {
  const mailbox = await db.companyMailbox.findUnique({ where: { address: FROM_ADDRESS } });
  if (!mailbox) throw new Error(`No CompanyMailbox row for ${FROM_ADDRESS}`);
  const password = decryptSecret(mailbox.passwordEnc);
  if (!password) throw new Error(`Could not decrypt password for ${FROM_ADDRESS}.`);
  const displayName = mailbox.displayName || mailbox.label || "Santino";
  const signatureHtml = mailbox.signatureHtml?.trim();
  if (!signatureHtml) throw new Error(`${FROM_ADDRESS} has no signatureHtml saved.`);
  const signatureText = (mailbox.signature || `${displayName}\nOwner, Nxeon\nnxeon.cloud | ${FROM_ADDRESS}`).trim();
  const brand = await db.brand.findFirst({ where: { name: "Nxeon" }, select: { name: true, physicalPostalAddress: true } });
  const postalAddress = brand?.physicalPostalAddress?.trim();
  if (!postalAddress) throw new Error("Brand 'Nxeon' has no physicalPostalAddress set.");
  const footerHtml = `<p style="margin:24px 0 0;padding-top:16px;border-top:1px solid #e5e5e5;font-family:Arial,Helvetica,sans-serif;font-size:12px;line-height:1.6;color:#8a8a8a;">${brand!.name} · ${postalAddress}<br>Don't want these emails? Reply with "UNSUBSCRIBE" and we'll stop contacting you.</p>`;
  const footerText = `\n\n---\n${brand!.name} · ${postalAddress}\nDon't want these emails? Reply with "UNSUBSCRIBE" and we'll stop contacting you.`;
  const smtp = nodemailer.createTransport({
    host: MAIL_SMTP_HOST, port: MAIL_SMTP_PORT, secure: MAIL_SMTP_PORT === 465,
    requireTLS: MAIL_SMTP_PORT !== 465, tls: mailTlsOptions(), auth: { user: FROM_ADDRESS, pass: password },
  });
  await smtp.verify();
  return { displayName, password, signatureHtml, signatureText, footerHtml, footerText, smtp };
}

export type OutreachRow = {
  email: string;
  fullName: string;
  game: string;
  channelUrl?: string | null;
  country?: string | null;
  subscribers?: string | null;
};

/**
 * Send the outreach email to ONE recipient: ensures a DRAFT creator invite
 * exists (idempotent), rotates its token for a real live claim link, sends,
 * best-effort copies to the Sent folder, and logs to EmailLog (open/click
 * tracking rides on the same recordEmail() every other platform email uses).
 * Never throws — resolves {ok:false, error} instead, so a queue drain never
 * dies on one bad row.
 */
export async function sendOutreachEmailTo(
  ctx: OutreachMailerContext,
  row: OutreachRow
): Promise<{ ok: true; messageId: string; claimUrl: string } | { ok: false; error: string }> {
  const { email } = row;
  const fullName = row.fullName || "there";
  const game = row.game || "your game";
  const vars = { fullName, firstName: firstNameOf(fullName), game };
  try {
    await createCreatorDrafts(
      [{ email, name: fullName, primaryGame: game, channelUrl: row.channelUrl ?? undefined, country: row.country ?? undefined, subscribers: row.subscribers ?? undefined }],
      { invitedById: null, dryRun: false }
    );
    const inv = await db.partnerInvite.findFirst({ where: { kind: "CREATOR", email, revokedAt: null }, orderBy: { createdAt: "desc" } });
    if (!inv) throw new Error("could not create or find a draft invite (already a partner?)");

    const token = randomBytes(32).toString("base64url");
    const now = new Date();
    await db.partnerInvite.update({
      where: { id: inv.id },
      data: { tokenHash: hashInviteToken(token), expiresAt: new Date(now.getTime() + CREATOR_INVITE_TTL_DAYS * 86_400_000), lastSentAt: now, sendCount: { increment: 1 } },
    });
    const claimUrl = creatorClaimUrl(token);

    const { subject, html, text } = buildEmail(vars, claimUrl);
    const fullHtml = [html, `<div style="margin-top:22px;">${ctx.signatureHtml}</div>`, ctx.footerHtml].join("\n");
    const fullText = [text, "", ctx.signatureText, ctx.footerText].join("\n\n");

    const composer = nodemailer.createTransport({ streamTransport: true, buffer: true, newline: "\r\n" });
    const built = await composer.sendMail({
      from: { name: ctx.displayName, address: FROM_ADDRESS }, to: email, subject, text: fullText, html: fullHtml,
    });
    const raw = built.message as Buffer;
    const info = await ctx.smtp.sendMail({ envelope: built.envelope, raw });

    try {
      await withImap({ address: FROM_ADDRESS, password: ctx.password }, async (client) => {
        const sentPath = await findSentPath(client as never);
        await client.append(sentPath, raw, ["\\Seen"]);
      });
    } catch {
      // Best-effort — the message was already delivered via SMTP above.
    }

    await recordEmail(email, subject, "creator_partner_invite_custom", fullHtml, "SENT");
    return { ok: true, messageId: info.messageId, claimUrl };
  } catch (err: unknown) {
    return { ok: false, error: err instanceof Error ? err.message : String(err) };
  }
}
"use server";

/**
 * Admin-only: upload a creator CSV (same columns as scripts/partner-invite-
 * batch.ts / creator-outreach-invite-send.ts) and queue it for the creator-
 * outreach template, drained by the worker at one email per minute
 * (worker/index.ts's processOutreachQueueTick → lib/creator-outreach-send-
 * core.ts). Never sends inline — this only writes OutreachQueueItem rows.
 */
import { db } from "./db";
import { requireAdmin } from "./auth";
import { parseCreatorCsv } from "./partner-invite-core";

export async function uploadOutreachCsv(
  csvText: string
): Promise<{ error?: string; queued?: number; skipped?: number }> {
  await requireAdmin();

  const { rows, error } = parseCreatorCsv(csvText);
  if (error) return { error };
  if (rows.length === 0) return { error: "No rows found in that CSV." };

  const emails = rows.map((r) => r.email.toLowerCase()).filter(Boolean);
  const [existingInvites, existingQueued] = await Promise.all([
    db.partnerInvite.findMany({ where: { kind: "CREATOR", email: { in: emails }, revokedAt: null }, select: { email: true } }),
    db.outreachQueueItem.findMany({ where: { email: { in: emails }, status: { in: ["QUEUED", "SENT"] } }, select: { email: true } }),
  ]);
  const already = new Set([...existingInvites, ...existingQueued].map((r) => r.email.toLowerCase()));

  const toQueue = rows.filter((r) => r.email && !already.has(r.email.toLowerCase()));
  if (toQueue.length > 0) {
    await db.outreachQueueItem.createMany({
      data: toQueue.map((r) => ({
        email: r.email,
        fullName: r.name || "there",
        game: r.game || "your game",
        channelUrl: r.channel || null,
        country: r.country || null,
        subscribers: r.subscribers || null,
      })),
    });
  }

  return { queued: toQueue.length, skipped: rows.length - toQueue.length };
}

/** For the admin page's "N queued, sending ~1/min" status line. */
export async function outreachQueueStatus(): Promise<{ queued: number; sentToday: number; failed: number }> {
  await requireAdmin();
  const since = new Date(Date.now() - 24 * 60 * 60_000);
  const [queued, sentToday, failed] = await Promise.all([
    db.outreachQueueItem.count({ where: { status: "QUEUED" } }),
    db.outreachQueueItem.count({ where: { status: "SENT", sentAt: { gte: since } } }),
    db.outreachQueueItem.count({ where: { status: "FAILED" } }),
  ]);
  return { queued, sentToday, failed };
}
"use client";

import { useState, useTransition } from "react";
import { uploadOutreachCsv } from "@/lib/actions-outreach-queue";

/**
 * Upload a creator CSV for the outreach-template campaign — queues rows for
 * the worker's 1-per-minute drain (worker/index.ts processOutreachQueueTick).
 * Never sends inline.
 */
export function OutreachQueueUpload({ initialStatus }: { initialStatus: { queued: number; sentToday: number; failed: number } }) {
  const [status, setStatus] = useState(initialStatus);
  const [msg, setMsg] = useState<string | null>(null);
  const [pending, startTransition] = useTransition();

  function onFile(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      const text = String(reader.result ?? "");
      startTransition(async () => {
        const res = await uploadOutreachCsv(text);
        if (res.error) setMsg(`Error: ${res.error}`);
        else {
          setMsg(`Queued ${res.queued} — skipped ${res.skipped} (already invited/queued).`);
          setStatus((s) => ({ ...s, queued: s.queued + (res.queued ?? 0) }));
        }
      });
    };
    reader.readAsText(file);
    e.target.value = "";
  }

  return (
    <div className="rounded-xl border border-white/10 bg-white/[0.02] p-4 text-sm">
      <div className="mb-2 font-semibold text-white">Creator outreach CSV queue</div>
      <div className="mb-3 text-slate-400">
        {status.queued} queued · {status.sentToday} sent today · {status.failed} failed. Sends at most one email per minute.
      </div>
      <label className="inline-flex cursor-pointer items-center rounded-lg border border-white/10 bg-white/5 px-3 py-1.5 hover:bg-white/10">
        <input type="file" accept=".csv" className="hidden" onChange={onFile} disabled={pending} />
        {pending ? "Uploading…" : "Upload CSV"}
      </label>
      {msg && <div className="mt-2 text-slate-300">{msg}</div>}
    </div>
  );
}

// Creator Partner Program — CREATOR invite core (2026-09-27). Plain server
// module (NOT "use server"): shared by the admin server actions
// (lib/actions-partner-invite.ts), the admin email-preview route
// (app/admin/partners/invite-preview/route.ts) and the batch script
// (scripts/partner-invite-batch.ts). Callers do their own auth.
//
// Lifecycle: DRAFT (created, `lastSentAt` null, token hash is a random value
// nobody holds — the invite cannot be claimed) -> SENT (an explicit admin Send
// rotates the token, sets the expiry, emails it) -> ACCEPTED / EXPIRED /
// REVOKED. Nothing in this module sends on creation.

import { randomBytes, createHash } from "node:crypto";
import { db } from "./db";
import { emails, type BuiltEmail } from "./email-templates";

export const CREATOR_DEFAULT_RATE = 40; // the program's published lifetime rate
export const CREATOR_INVITE_TTL_DAYS = 14;

export const hashInviteToken = (t: string) => createHash("sha256").update(t).digest("hex");
const appBase = () => (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/+$/, "");
export const creatorClaimUrl = (token: string) => `${appBase()}/partner/claim?token=${encodeURIComponent(token)}`;
/** Used for previews: a well-formed link whose token matches no invite. */
export const PREVIEW_TOKEN = "PREVIEW-ONLY-this-link-is-not-valid";

export type InviteState = "draft" | "sent" | "accepted" | "expired" | "revoked";
export function creatorInviteState(i: { acceptedAt: Date | null; revokedAt: Date | null; lastSentAt: Date | null; expiresAt: Date }, now = new Date()): InviteState {
  if (i.acceptedAt) return "accepted";
  if (i.revokedAt) return "revoked";
  if (!i.lastSentAt) return "draft";
  if (i.expiresAt < now) return "expired";
  return "sent";
}

// ---------- the owner's creator CSV ----------

/** One row of the owner's creator list. Header (case/space-insensitive):
 *  Name, Youtube Channel, Primary game, Email, Current Hosting Sponsor (If
 *  Applicable), Country, Subscriber count, Emailed. */
export type CreatorRow = {
  name: string;
  channel: string;
  game: string;
  email: string;
  country: string;
  subscribers: string;
};

/** Minimal RFC-4180 CSV parser (quoted fields, "" escapes, CRLF). */
function parseCsv(text: string): string[][] {
  const rows: string[][] = [];
  let row: string[] = [];
  let field = "";
  let q = false;
  const s = text.replace(/^﻿/, "");
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (q) {
      if (ch === '"') {
        if (s[i + 1] === '"') { field += '"'; i++; } else q = false;
      } else field += ch;
    } else if (ch === '"') q = true;
    else if (ch === ",") { row.push(field); field = ""; }
    else if (ch === "\n" || ch === "\r") {
      if (ch === "\r" && s[i + 1] === "\n") i++;
      row.push(field); field = "";
      if (row.some((c) => c.trim() !== "")) rows.push(row);
      row = [];
    } else field += ch;
  }
  row.push(field);
  if (row.some((c) => c.trim() !== "")) rows.push(row);
  return rows;
}

export function parseCreatorCsv(text: string): { rows: CreatorRow[]; error?: string } {
  const all = parseCsv(text);
  if (all.length === 0) return { rows: [], error: "The CSV is empty." };
  const head = all[0].map((h) => h.trim().toLowerCase().replace(/\s+/g, " "));
  const col = (...names: string[]) => head.findIndex((h) => names.some((n) => h === n || h.startsWith(n)));
  const iEmail = col("email");
  const iName = col("name");
  if (iEmail < 0 || iName < 0) return { rows: [], error: "The CSV needs at least a Name and an Email column." };
  const iChannel = col("youtube channel", "channel");
  const iGame = col("primary game", "game");
  const iCountry = col("country");
  const iSubs = col("subscriber count", "subscribers");
  const get = (r: string[], i: number) => (i >= 0 ? (r[i] ?? "").trim() : "");
  const rows = all.slice(1).map((r) => ({
    name: get(r, iName),
    channel: get(r, iChannel),
    game: get(r, iGame),
    email: get(r, iEmail).toLowerCase(),
    country: get(r, iCountry),
    subscribers: get(r, iSubs),
  })).filter((r) => r.email);
  return { rows };
}

export function normalizeEmails(raw: string): { emails: string[]; invalid: string[] } {
  const list = [...new Set(raw.split(/[\s,;]+/).map((e) => e.trim().toLowerCase()).filter(Boolean))];
  const ok = (e: string) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e) && e.length <= 200;
  return { emails: list.filter(ok), invalid: list.filter((e) => !ok(e)) };
}

/** Match pasted emails to CSV rows — exact (case-insensitive) email match only, never a guess. */
export function matchCreators(emailsIn: string[], rows: CreatorRow[]): { matched: { email: string; row: CreatorRow }[]; unmatched: string[] } {
  const byEmail = new Map<string, CreatorRow>();
  for (const r of rows) if (!byEmail.has(r.email)) byEmail.set(r.email, r);
  const matched: { email: string; row: CreatorRow }[] = [];
  const unmatched: string[] = [];
  for (const e of emailsIn) {
    const r = byEmail.get(e);
    if (r) matched.push({ email: e, row: r }); else unmatched.push(e);
  }
  return { matched, unmatched };
}

/** Keep only http(s) links in the channel field (it is later rendered as a link). */
export function safeChannelUrl(v: string | null | undefined): string | null {
  const s = (v ?? "").trim();
  if (!s) return null;
  try {
    const u = new URL(s);
    return u.protocol === "https:" || u.protocol === "http:" ? u.toString().slice(0, 300) : null;
  } catch {
    return null;
  }
}

// ---------- drafts ----------

export type DraftEntry = {
  email: string;
  name?: string | null;
  channelUrl?: string | null;
  primaryGame?: string | null;
  country?: string | null;
  subscribers?: string | null;
};
export type DraftResult = { email: string; name: string | null; channel: string | null; status: "created" | "would create" | "skipped"; reason?: string };

/**
 * Create DRAFT creator invites. Never sends. Idempotent: an email that already
 * has a non-revoked CREATOR invite (draft, sent, accepted or expired), or whose
 * account is already a partner, is skipped.
 */
export async function createCreatorDrafts(
  entries: DraftEntry[],
  opts: { invitedById: string | null; ratePct?: number; note?: string | null; allowAnyEmail?: boolean; dryRun?: boolean }
): Promise<DraftResult[]> {
  const rate = Number.isFinite(opts.ratePct) ? Math.min(90, Math.max(1, Math.round((opts.ratePct as number) * 100) / 100)) : CREATOR_DEFAULT_RATE;
  const out: DraftResult[] = [];
  for (const e of entries) {
    const email = e.email.trim().toLowerCase();
    const name = e.name?.trim().slice(0, 120) || null;
    const channel = safeChannelUrl(e.channelUrl);
    const user = await db.user.findUnique({ where: { email }, select: { referralPartner: { select: { code: true } } } });
    if (user?.referralPartner) {
      out.push({ email, name, channel, status: "skipped", reason: `already a partner (${user.referralPartner.code})` });
      continue;
    }
    const existing = await db.partnerInvite.findFirst({
      where: { kind: "CREATOR", email, revokedAt: null },
      orderBy: { createdAt: "desc" },
    });
    if (existing) {
      out.push({ email, name, channel, status: "skipped", reason: `already invited (${creatorInviteState(existing)})` });
      continue;
    }
    if (opts.dryRun) {
      out.push({ email, name, channel, status: "would create" });
      continue;
    }
    await db.partnerInvite.create({
      data: {
        kind: "CREATOR",
        email,
        // A random hash nobody holds the preimage of: a draft can't be claimed.
        tokenHash: hashInviteToken(randomBytes(32).toString("base64url")),
        invitedById: opts.invitedById,
        expiresAt: new Date(), // real expiry is set when the invite is sent
        name,
        note: opts.note?.trim().slice(0, 500) || null,
        ratePct: rate,
        allowAnyEmail: !!opts.allowAnyEmail,
        channelUrl: channel,
        primaryGame: e.primaryGame?.trim().slice(0, 80) || null,
        country: e.country?.trim().slice(0, 80) || null,
        subscribers: e.subscribers?.trim().slice(0, 40) || null,
        lastSentAt: null,
        sendCount: 0,
      },
    });
    out.push({ email, name, channel, status: "created" });
  }
  return out;
}

// ---------- rendering + sending ----------

type RenderableInvite = { email: string; name: string | null; ratePct: number | null; allowAnyEmail: boolean };

/** The exact email a creator receives (the send path calls this too). */
export function renderCreatorInviteEmail(inv: RenderableInvite, claimUrl: string, expiresAt: Date): BuiltEmail {
  return emails.creatorPartnerInvite({
    name: inv.name,
    email: inv.email,
    ratePct: inv.ratePct ?? CREATOR_DEFAULT_RATE,
    claimUrl,
    expires: expiresAt.toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric", timeZone: "UTC" }),
    anyEmail: inv.allowAnyEmail,
  });
}

/** Preview: the same render with a token that matches no invite, and the expiry a send made now would get. */
export function renderCreatorInvitePreview(inv: RenderableInvite): BuiltEmail {
  return renderCreatorInviteEmail(inv, creatorClaimUrl(PREVIEW_TOKEN), new Date(Date.now() + CREATOR_INVITE_TTL_DAYS * 86_400_000));
}

/**
 * Send (or re-send) one creator invite: rotate the token (older links die),
 * set a fresh expiry, email it. Returns the new link ONCE (only its hash is
 * stored) so an admin can also deliver it by hand if mail isn't configured.
 *
 * `opts.fromMailbox`: deliver through a real CompanyMailbox (e.g.
 * santino@nxeon.cloud) instead of the platform's generic transactional
 * sender — for creators who already have a personal outreach relationship
 * with that mailbox's owner from the initial sponsorship blast, so the
 * invite arrives as a continuation of that thread rather than a "Nxeon"
 * system email. A copy is saved to that mailbox's Sent folder either way.
 * Every DB side effect (token rotation, expiry, sendCount, lastSentAt) is
 * identical regardless of which transport is used.
 */
export async function sendCreatorInvite(
  inviteId: string,
  opts?: { fromMailbox?: string },
): Promise<{ ok: boolean; error?: string; email?: string; sent?: boolean; link?: string }> {
  const inv = await db.partnerInvite.findUnique({ where: { id: inviteId } });
  if (!inv || inv.kind !== "CREATOR") return { ok: false, error: "Invite not found." };
  if (inv.acceptedAt) return { ok: false, email: inv.email, error: "Already claimed." };
  if (inv.revokedAt) return { ok: false, email: inv.email, error: "Revoked — create a new invite instead." };

  const token = randomBytes(32).toString("base64url");
  const now = new Date();
  const updated = await db.partnerInvite.update({
    where: { id: inv.id },
    data: {
      tokenHash: hashInviteToken(token),
      expiresAt: new Date(now.getTime() + CREATOR_INVITE_TTL_DAYS * 86_400_000),
      lastSentAt: now,
      sendCount: { increment: 1 },
    },
  });
  const link = creatorClaimUrl(token);
  const tpl = renderCreatorInviteEmail(updated, link, updated.expiresAt);

  if (opts?.fromMailbox) {
    const sent = await sendViaCompanyMailbox(opts.fromMailbox, updated.email, tpl.subject, tpl.html);
    // Record it the same way lib/mailer.ts's sendMail() would — the admin
    // partners page reads EmailLog by (toEmail, template: "creator_partner_invite")
    // to show delivered/opened state. Without this row a real, successfully
    // delivered send still shows as "sent · not delivered" in the admin UI.
    const { recordEmail } = await import("./email-render");
    await recordEmail(updated.email, tpl.subject, tpl.template, tpl.html, sent ? "SENT" : "FAILED");
    return { ok: true, email: updated.email, sent, link };
  }

  const { sendMail } = await import("./mailer");
  const sent = await sendMail({ to: updated.email, subject: tpl.subject, html: tpl.html, template: tpl.template });
  return { ok: true, email: updated.email, sent, link };
}

/** Send one HTML email through a real CompanyMailbox over SMTP (not the
 *  platform's generic transactional sender), and save a copy to its Sent
 *  folder — same mechanism as the native webmail composer
 *  (lib/actions-mail.ts::sendMessage), factored out here for callers that
 *  need to send AS a specific staff mailbox rather than "Nxeon <...>". */
async function sendViaCompanyMailbox(fromAddress: string, to: string, subject: string, html: string): Promise<boolean> {
  const [{ default: nodemailer }, { decryptSecret }, { mailTlsOptions, withImap }] = await Promise.all([
    import("nodemailer"),
    import("./crypto-box"),
    import("./mail/imap"),
  ]);
  const mailbox = await db.companyMailbox.findUnique({ where: { address: fromAddress } });
  if (!mailbox) return false;
  const password = decryptSecret(mailbox.passwordEnc);
  if (!password) return false;
  const displayName = mailbox.displayName || mailbox.label || fromAddress.split("@")[0];

  const composer = nodemailer.createTransport({ streamTransport: true, buffer: true, newline: "\r\n" });
  const built = await composer.sendMail({ from: { name: displayName, address: fromAddress }, to, subject, html });
  const raw = built.message as Buffer;

  const smtp = nodemailer.createTransport({
    host: process.env.MAIL_SMTP_HOST || "10.20.0.10",
    port: Number(process.env.MAIL_SMTP_PORT || 587),
    secure: Number(process.env.MAIL_SMTP_PORT || 587) === 465,
    requireTLS: Number(process.env.MAIL_SMTP_PORT || 587) !== 465,
    tls: mailTlsOptions(),
    auth: { user: fromAddress, pass: password },
  });
  try {
    await smtp.sendMail({ envelope: built.envelope, raw });
  } catch {
    return false;
  }
  try {
    await withImap({ address: fromAddress, password }, async (client) => {
      const list = await client.list();
      const sentPath = list.find((f) => f.specialUse === "\\Sent" || /sent/i.test(f.path))?.path || "Sent";
      await client.append(sentPath, raw, ["\\Seen"]);
    });
  } catch {
    /* best-effort — the message already went out */
  }
  return true;
}

// ---------- the stored master list ----------

/**
 * The owner's master creator CSV, as uploaded to the admin board ("Creator
 * Affiliate Outreach - v1.csv" on the "Full reachout" card). Looked up by
 * attachment name, newest first, so a v2 upload is picked up automatically;
 * the "- test" list is ignored. Null when there isn't one (e.g. on staging).
 */
export async function findMasterCreatorCsv(): Promise<{ path: string; filename: string; uploadedAt: Date } | null> {
  const { BOARD_UPLOAD_DIR } = await import("./board-shared");
  const { join } = await import("node:path");
  const att = await db.cardAttachment.findFirst({
    where: { filename: { startsWith: "Creator Affiliate Outreach - v", mode: "insensitive" } },
    orderBy: { createdAt: "desc" },
    select: { cardId: true, storedName: true, filename: true, createdAt: true },
  });
  if (!att || !att.filename.toLowerCase().endsWith(".csv")) return null;
  return { path: join(BOARD_UPLOAD_DIR, "board", att.cardId, att.storedName), filename: att.filename, uploadedAt: att.createdAt };
}
