export const dynamic = "force-dynamic";

// The Partners admin page, split into three in-page tabs (same `?tab=` strip
// convention as /admin/logs) so the analytics, the partner list and the creator
// invite tools each get their own screen instead of one long mixed scroll:
//   overview  program-wide analytics (ProgramOverview.tsx)
//   partners  every partner + add a partner
//   invites   creator recruitment figures, the invite drafting form, the invites table
// Only the active tab's data is queried.

const TABS = [
  { key: "overview", label: "Overview" },
  { key: "partners", label: "Partners" },
  { key: "invites", label: "Creator invites" },
] as const;
type Tab = (typeof TABS)[number]["key"];

export default async function AdminPartnersPage({
  searchParams,
}: {
  searchParams: Promise<OverviewQuery & { tab?: string }>;
}) {
  await requireArea("billing");
  const sp = await searchParams;
  const tab: Tab = TABS.some((t) => t.key === sp.tab) ? (sp.tab as Tab) : "overview";

  const [currency, partnerCount, inviteCount, draftCount] = await Promise.all([
    currentCurrency(),
    db.referralPartner.count(),
    db.partnerInvite.count({ where: { kind: "CREATOR" } }),
    // Same definition as creatorInviteState's "draft": never sent, not accepted, not revoked.
    db.partnerInvite.count({ where: { kind: "CREATOR", lastSentAt: null, acceptedAt: null, revokedAt: null } }),
  ]);
  const counts: Record<Tab, string | null> = {
    overview: null,
    partners: String(partnerCount),
    invites: draftCount > 0 ? `${inviteCount} · ${draftCount} draft${draftCount === 1 ? "" : "s"}` : String(inviteCount),
  };

  return (
    <div className="space-y-6">
      <PageHeader
        title="Partners (KOL / Agency)"
        sub="Agencies and creators earn a lifetime commission on every charge their referred customers make. Program analytics, partners, rates, settlements and creator invites."
      />

      <nav className="flex gap-1 overflow-x-auto rounded-xl border border-white/[0.06] bg-white/[0.02] p-1" aria-label="Partners sections">
        {TABS.map((t) => (
          <Link
            key={t.key}
            href={`/admin/partners?tab=${t.key}`}
            aria-current={tab === t.key ? "page" : undefined}
            className={`flex shrink-0 items-center gap-2 rounded-lg px-4 py-1.5 text-sm font-medium transition-colors ${
              tab === t.key ? "bg-gradient-to-r from-accent-blue to-brand-500 text-white" : "text-slate-400 hover:text-white"
            }`}
          >
            {t.label}
            {counts[t.key] && (
              <span className={`text-xs ${tab === t.key ? "text-white/80" : "text-slate-500"}`}>{counts[t.key]}</span>
            )}
          </Link>
        ))}
      </nav>

      {tab === "overview" && <ProgramOverview query={sp} currency={currency} />}
      {tab === "partners" && <PartnersTab currency={currency} />}
      {tab === "invites" && <InvitesTab />}
    </div>
  );
}

async function PartnersTab({ currency }: { currency: string }) {
  const partners = await db.referralPartner.findMany({
    orderBy: { createdAt: "desc" },
    take: 500,
    include: {
      user: { select: { email: true } },
      _count: { select: { customers: true } },
    },
  });

  // Commission totals per partner, by status (bounded to the listed partners).
  const totals = await Promise.all(
    partners.map((p) =>
      db.partnerCommission.groupBy({
        by: ["status"],
        where: { partnerId: p.id },
        _sum: { amountCents: true },
      })
    )
  );
  const sumFor = (i: number, status: string) => totals[i].find((t) => t.status === status)?._sum.amountCents ?? 0;

  return (
    <div className="space-y-6">
      <div className="card overflow-x-auto p-0">
        <div className="px-4 pt-4">
          <p className="section-label">All partners</p>
          <p className="mt-1 text-xs text-slate-500">
            Open a partner to change their rate or status, attach customers, record payouts and see their ledger.
          </p>
        </div>
        {partners.length === 0 ? (
          <p className="px-4 py-8 text-sm text-slate-400">No partners yet. Add one below.</p>
        ) : (
          <table className="table-shell mt-2 min-w-[820px]">
            <thead>
              <tr>
                <th>Partner</th>
                <th>Code</th>
                <th className="text-right">Rate</th>
                <th className="text-right">Customers</th>
                <th className="text-right">Accrued</th>
                <th className="text-right">Paid</th>
                <th>Status</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
              {partners.map((p, i) => (
                <tr key={p.id}>
                  <td>
                    <div className="text-slate-200">{p.name}</div>
                    <div className="text-xs text-slate-500">{p.user?.email ?? p.contactEmail ?? "no login"}</div>
                  </td>
                  <td className="font-mono text-brand-200">{p.code}</td>
                  <td className="text-right font-mono">{p.commissionRatePct}%</td>
                  <td className="text-right font-mono">{p._count.customers}</td>
                  <td className="text-right font-mono">{formatMoney(sumFor(i, "ACCRUED"), currency)}</td>
                  <td className="text-right font-mono text-emerald-400">{formatMoney(sumFor(i, "PAID"), currency)}</td>
                  <td>
                    <Badge tone={p.status === "ACTIVE" ? "green" : "slate"}>{p.status.toLowerCase()}</Badge>
                  </td>
                  <td className="text-right">
                    <Link href={`/admin/partners/${p.id}`} className="text-brand-300 hover:underline">
                      Manage
                    </Link>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      <div className="card space-y-4">
        <div>
          <p className="section-label">Add a partner</p>
          <p className="mt-1 text-sm text-slate-400">
            For an agency or partner you set up by hand. Creators normally join through an invite instead — see the
            Creator invites tab.
          </p>
        </div>
        <CreatePartnerForm />
      </div>
    </div>
  );
}

async function InvitesTab() {
  // Creator invites (lib/actions-partner-invite.ts) + the delivery state of
  // each one's latest email, from EmailLog (SENT/FAILED, and openedAt from the
  // tracking pixel — "opened" only when the recipient's client loads images).
  const [creatorInvites, recruitment, master, outreachStatus] = await Promise.all([
    db.partnerInvite.findMany({
      where: { kind: "CREATOR" },
      orderBy: { createdAt: "desc" },
      take: 200,
      include: { partner: { select: { id: true, code: true } } },
    }),
    creatorRecruitmentStats(),
    findMasterCreatorCsv(),
    outreachQueueStatus(),
  ]);
  const inviteMail = creatorInvites.length
    ? await db.emailLog.findMany({
        // `startsWith` — a bespoke/hand-worded invite (e.g. lib/partner-invite-core.ts's
        // sendCreatorInvite custom-mailbox path, or an ad-hoc admin script) logs under
        // "creator_partner_invite_custom", not the plain template. An exact match here
        // made every custom-worded send show as "sent · not delivered" even when it sent
        // fine — real EmailLog row, just invisible to this query (found 2026-09-29,
        // Zeroster's invite).
        where: { template: { startsWith: "creator_partner_invite" }, toEmail: { in: [...new Set(creatorInvites.map((i) => i.email))] } },
        orderBy: { createdAt: "desc" },
        select: { toEmail: true, status: true, openedAt: true, createdAt: true },
        take: 1000,
      })
    : [];
  const inviteState = (i: (typeof creatorInvites)[number]) => {
    const st = creatorInviteState(i);
    if (st === "draft") return { label: "draft", tone: "slate" as const };
    if (st === "accepted") return { label: "accepted", tone: "green" as const };
    if (st === "revoked") return { label: "revoked", tone: "slate" as const };
    if (st === "expired") return { label: "expired", tone: "slate" as const };
    const sentAt = (i.lastSentAt ?? i.createdAt).getTime() - 60_000;
    const mail = inviteMail.find((m) => m.toEmail === i.email && m.createdAt.getTime() >= sentAt);
    if (!mail || mail.status !== "SENT") return { label: "sent · not delivered", tone: "red" as const };
    if (mail.openedAt) return { label: "sent · opened", tone: "brand" as const };
    return { label: "sent", tone: "amber" as const };
  };
  const drafts = creatorInvites.filter((i) => creatorInviteState(i) === "draft");
  const sentEver = recruitment.total - recruitment.drafts;

  const stats: { label: string; value: number; note?: string; tone?: string }[] = [
    { label: "Invites", value: recruitment.total },
    { label: "Drafts (not emailed)", value: recruitment.drafts },
    { label: "Sent, awaiting a claim", value: recruitment.outstanding },
    {
      label: "Claimed (became partners)",
      value: recruitment.accepted,
      note: sentEver > 0 ? `${Math.round((recruitment.accepted / sentEver) * 100)}% of sent` : undefined,
      tone: "text-emerald-400",
    },
    { label: "Expired / revoked", value: recruitment.expired + recruitment.revoked },
    {
      label: "Claimed creators with a click",
      value: recruitment.claimedWithClick,
      note: `of ${recruitment.accepted} — have had at least one visit to their link`,
    },
  ];

  return (
    <div className="space-y-6">
      <OutreachQueueUpload initialStatus={outreachStatus} />
      <div className="card">
        <div className="flex flex-wrap items-baseline justify-between gap-2">
          <p className="section-label">Creator recruitment · all time</p>
          <p className="text-xs text-slate-500">Every creator invite, drafted → sent → claimed.</p>
