        console.log(`[billing] renewed ${server.hostname} until ${newExpiry.toISOString()}`);
      }
    } else if (cardInPlay) {
      // Only attempt on the scheduled day. Without this gate a 10-minute sweep
      // would burn all three retries — and send all three emails — within half an
      // hour of the first decline.
      //
      // A scheduled time, once set, ALWAYS wins over the attempt counter, which buys
      // two things. `retryDunningNow` (fired when a customer saves a new card
      // mid-dunning) gets a real attempt even at the exhausted stage — refusing there
      // would suspend a customer whose brand-new card we never once tried. And the
      // exhausted stage's schedule points at the suspension day itself, so every
      // server gets one final, silent try at the card in the same pass that pauses it.
      const dueForRetry = server.dunningNextAt
        ? now >= server.dunningNextAt
        : server.dunningStage < DUNNING_EXHAUSTED;
      if (dueForRetry) {
        renewed = (
          await attemptCardRenewal({
            server,
            charge,
            cardCents: split.cardCents,
            newExpiry,
            now,
            cfg,
            taxCountry: taxCtx.country,
          })
