const TOKEN_VERSION = "v1";

/** HMAC key. AUTH_SECRET is the platform's shared signing secret. */
function signingKey(): string {
  const secret = process.env.AUTH_SECRET;
  if (!secret || !secret.trim()) {
    throw new Error("AUTH_SECRET is not set — cannot sign unsubscribe tokens");
  }
  return secret;
}

