/** Stateless, tamper-proof unsubscribe tokens for outreach emails (HMAC over the address). */
import { createHmac, timingSafeEqual } from "node:crypto";

function key(): string {
  const s = process.env.AUTH_SECRET;
  if (!s || !s.trim()) throw new Error("AUTH_SECRET is not set — cannot sign unsubscribe tokens");
  return s;
}
const sign = (p: string) => createHmac("sha256", key()).update(`outreach-unsub:${p}`).digest("base64url");

export function outreachUnsubToken(email: string): string {
  const body = Buffer.from(email.trim().toLowerCase(), "utf8").toString("base64url");
  return `${body}.${sign(body)}`;
}
export function verifyOutreachUnsubToken(token: string): string | null {
  const [body, sig] = String(token || "").split(".");
  if (!body || !sig) return null;
  const want = Buffer.from(sign(body));
  const got = Buffer.from(sig);
  if (want.length !== got.length || !timingSafeEqual(want, got)) return null;
  const email = Buffer.from(body, "base64url").toString("utf8");
  return /^[^\s@]+@[^\s@]+$/.test(email) ? email : null;
}
export function outreachUnsubUrl(email: string): string {
  const base = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/+$/, "");
  return `${base}/api/outreach/unsubscribe?t=${encodeURIComponent(outreachUnsubToken(email))}`;
}
