/**
 * Pacing / send-window / daily-cap / warm-up math for outreach campaigns.
 * PURE: every function takes `now` (and `rand`) explicitly so it is unit-testable.
 */
export type PacingConfig = {
  intervalSeconds: number;
  jitterPct: number;
  windowStartHour: number | null;
  windowEndHour: number | null;
  timezone: string;
  days: string; // "1,2,3,4,5" ISO weekdays (1=Mon..7=Sun)
  dailyCap: number | null;
  warmupEnabled: boolean;
  warmupStartCap: number;
  warmupStep: number;
};

export const MIN_INTERVAL_SECONDS = 5;
export const MAX_INTERVAL_SECONDS = 86_400;

/** Seconds until the next email: interval +/- jitterPct%, never below the floor. */
export function nextDelaySeconds(intervalSeconds: number, jitterPct: number, rand: () => number = Math.random): number {
  const base = Math.max(MIN_INTERVAL_SECONDS, intervalSeconds);
  const j = Math.min(100, Math.max(0, jitterPct)) / 100;
  const factor = 1 + (rand() * 2 - 1) * j;
  return Math.max(MIN_INTERVAL_SECONDS, Math.round(base * factor));
}

export function parseDays(days: string): number[] {
  const set = new Set(days.split(",").map((d) => Number(d.trim())).filter((d) => d >= 1 && d <= 7));
  return [...set].sort();
}

export function validTimezone(tz: string): boolean {
  try { new Intl.DateTimeFormat("en-US", { timeZone: tz }); return true; } catch { return false; }
}

export type LocalParts = { year: number; month: number; day: number; hour: number; minute: number; second: number; isoDow: number };

/** Wall-clock parts of `d` in `timeZone`. */
export function localParts(d: Date, timeZone: string): LocalParts {
  const f = new Intl.DateTimeFormat("en-US", {
    timeZone, hourCycle: "h23", year: "numeric", month: "numeric", day: "numeric",
    hour: "numeric", minute: "numeric", second: "numeric", weekday: "short",
  });
  const p: Record<string, string> = {};
  for (const x of f.formatToParts(d)) p[x.type] = x.value;
  const dow = ({ Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6, Sun: 7 } as Record<string, number>)[p.weekday] ?? 1;
  return { year: +p.year, month: +p.month, day: +p.day, hour: +p.hour % 24, minute: +p.minute, second: +p.second, isoDow: dow };
}

/** Local calendar-day key ("2026-10-01") — the unit the daily cap counts over. */
export function localDayKey(d: Date, timeZone: string): string {
  const p = localParts(d, timeZone);
