    return { row, verdict };
  });
}

export function summarize(v: { verdict: RowVerdict }[]): Record<RowVerdict, number> {
  const out = { ok: 0, "invalid-email": 0, "duplicate-in-file": 0, "already-queued": 0, "already-invited": 0, "already-partner": 0, suppressed: 0 } as Record<RowVerdict, number>;
  for (const x of v) out[x.verdict]++;
  return out;
}
