/**
 * Reply / bounce / unsubscribe detection from INBOX messages. The classifier is
 * PURE; `scanInbox` (lib/outreach/inbox-scan.ts) feeds it from a READ-ONLY IMAP
 * session — nothing in the mailbox is ever modified.
 */
export type InboundMessage = {
  uid: number;
  messageId: string | null;
  inReplyTo: string | null;
  fromAddress: string;
  fromName?: string;
  subject: string;
  date: Date;
  /** First ~4KB of the decoded text body (plain preferred). */
  text: string;
};

export type Inbound =
  | { kind: "BOUNCE"; email: string; detail: string }
  | { kind: "UNSUBSCRIBE"; email: string; detail: string }
  | { kind: "REPLY"; email: string; detail: string };

const BOUNCE_SENDER = /^(mailer-daemon|postmaster|mail-delivery-subsystem|mail\.delivery)@|mail delivery (system|subsystem)/i;
const BOUNCE_SUBJECT = /undeliver|delivery status notification|delivery (has )?failed|returned mail|failure notice|mail delivery failed|could not be delivered|address not found/i;
// Auto-responders must not count as human replies or unsubscribes.
const AUTO_SUBJECT = /^(auto(matic)?[ -]?reply|automatic reply|out of office|autoreply|vacation)/i;
const UNSUB_RE = /\b(unsubscribe|opt[ -]?out|remove me|stop (emailing|contacting|sending)|do not (email|contact)|take me off)\b/i;

/** Pull the failed recipient out of a DSN body. */
export function bouncedRecipient(text: string, candidates: Set<string>): string | null {
  const m = /Final-Recipient:\s*rfc822;\s*<?([^\s>;]+)/i.exec(text) || /Original-Recipient:\s*rfc822;\s*<?([^\s>;]+)/i.exec(text);
  if (m && candidates.has(m[1].toLowerCase())) return m[1].toLowerCase();
  // Otherwise any candidate address mentioned in the body.
  const lower = text.toLowerCase();
  for (const c of candidates) if (lower.includes(c)) return c;
  return null;
}

/**
 * `recipients` = lowercase addresses we have emailed (campaign recipients).
 * Returns null when the message is unrelated to outreach.
 */
export function classifyInbound(msg: InboundMessage, recipients: Set<string>): Inbound | null {
  const from = msg.fromAddress.toLowerCase();
  const subj = msg.subject || "";
  if (BOUNCE_SENDER.test(from) || BOUNCE_SENDER.test(msg.fromName || "") || (BOUNCE_SUBJECT.test(subj) && !recipients.has(from))) {
    const who = bouncedRecipient(msg.text, recipients);
    return who ? { kind: "BOUNCE", email: who, detail: subj.slice(0, 200) } : null;
  }
  if (!recipients.has(from)) return null;
  if (AUTO_SUBJECT.test(subj)) return null;
  if (UNSUB_RE.test(`${subj}\n${msg.text.slice(0, 1500)}`)) return { kind: "UNSUBSCRIBE", email: from, detail: subj.slice(0, 200) };
  // A reply = threaded (In-Reply-To) or a "Re:" subject from a known recipient.
  if (msg.inReplyTo || /^\s*(re|aw|sv)\s*:/i.test(subj)) return { kind: "REPLY", email: from, detail: subj.slice(0, 200) };
  // A fresh message from someone we emailed is still a response worth surfacing.
  return { kind: "REPLY", email: from, detail: subj.slice(0, 200) };
}
