/** Build a per-request imapflow client for the given credential. */
export function createImapClient(cred: MailboxCredentials): ImapFlow {
  return new ImapFlow({
    host: MAIL_IMAP_HOST,
    port: MAIL_IMAP_PORT,
    secure: true,
    // We connect by internal IP but the cert is for mail.nxeon.cloud — set SNI
    // and validation servername so TLS verifies against the right name.
    servername: MAIL_TLS_SERVERNAME,
    tls: mailTlsOptions(),
    auth: { user: cred.address, pass: cred.password },
    logger: false,
    disableAutoIdle: true,
    // ImapFlow's default connectionTimeout is 90s — measured live against
    // this exact mail server (2026-08-29): a single struggling connection
    // attempt genuinely took the full 90s to fail. app/admin/inbox/page.tsx
    // tries EACH company mailbox in sequence on a bad first pick, so with 5
    // mailboxes a single slow one could hang the whole admin inbox page for
    // several minutes. This host also shows real CPU pressure-stall metrics
    // (contention from an overcommitted physical node, not a Mailcow config
    // bug), so occasional slow connects are expected — 10s is generous for a
    // LAN hop but fails far faster than 90s when the server genuinely can't
    // respond. socketTimeout stays closer to the library default since it
    // covers in-progress operations (fetching messages), which can
    // legitimately take longer than a bare connect.
    connectionTimeout: 10_000,
    greetingTimeout: 8_000,
    socketTimeout: 30_000,
  });
}

