/**
 * DB-backed outreach rendering + sending. EVERY path (admin preview, test send,
 * worker send) goes through `renderOutreachFor` so the preview is the email.
 */
import { randomBytes } from "node:crypto";
import nodemailer from "nodemailer";
import { db } from "../db";
import { decryptSecret } from "../crypto-box";
import { mailTlsOptions, withImap } from "../mail/imap";
import { MAIL_SMTP_HOST, MAIL_SMTP_PORT } from "../mail/types";
import { recordEmail } from "../email-render";
import { injectEmailTracking } from "../mailer";
import {
  createCreatorDrafts, hashInviteToken, creatorClaimUrl, creatorInviteState,
  CREATOR_INVITE_TTL_DAYS, PREVIEW_TOKEN, renderCreatorInviteEmail,
} from "../partner-invite-core";
import { OUTREACH_V3_BODY, SUBJECT_TMPL } from "../creator-outreach-template";
import {
  assembleCodeEmail, assembleEmail, buildVars, htmlToText, renderBody, fillText,
  type RecipientLike, type RenderedOutreach, type TemplateVars,
} from "./render";
import { outreachUnsubUrl } from "./unsubscribe";

export const DEFAULT_SENDER = "santino@nxeon.cloud";
export const BUILTIN_OUTREACH_KEY = "creator-outreach-v3";
export const BUILTIN_STANDARD_KEY = "standard-creator-invite";
export const PREVIEW_EMAIL_LOG_ID = "PREVIEW";

// ---------- templates ----------

export type TemplateRow = { id: string; key: string | null; name: string; kind: string; subject: string; body: string };

/** Create/refresh the two built-in templates. Built-ins are read-only in the UI (duplicate to edit). */
export async function ensureBuiltInTemplates(): Promise<{ outreachId: string; standardId: string }> {
  const a = await db.outreachTemplate.upsert({
    where: { key: BUILTIN_OUTREACH_KEY },
    update: { name: "Creator outreach — founder pitch (v3)", subject: SUBJECT_TMPL, body: OUTREACH_V3_BODY, kind: "MARKDOWN", builtIn: true },
    create: { key: BUILTIN_OUTREACH_KEY, name: "Creator outreach — founder pitch (v3)", subject: SUBJECT_TMPL, body: OUTREACH_V3_BODY, kind: "MARKDOWN", builtIn: true },
  });
  const b = await db.outreachTemplate.upsert({
    where: { key: BUILTIN_STANDARD_KEY },
    update: { name: "Standard creator invite (stats table)", kind: "CODE", builtIn: true },
    create: { key: BUILTIN_STANDARD_KEY, name: "Standard creator invite (stats table)", subject: "You're invited to the Nxeon Creator Partner Program", body: "", kind: "CODE", builtIn: true },
  });
  return { outreachId: a.id, standardId: b.id };
}

/** Campaign-level copy overrides win over the template's. */
export function effectiveContent(t: TemplateRow, c?: { subjectOverride?: string | null; bodyOverride?: string | null } | null) {
  return {
    subject: c?.subjectOverride?.trim() ? c.subjectOverride : t.subject,
    body: c?.bodyOverride?.trim() ? c.bodyOverride : t.body,
  };
}

// ---------- sender ----------

export type SenderContext = {
  address: string;
  displayName: string;
  signatureHtml: string;
  signatureText: string;
  brandName: string;
  postalAddress: string;
  /** Mailbox password — only needed for the Sent-folder copy + inbox scan. */
  password: string | null;
};

export async function loadSenderContext(address: string, opts: { needPassword?: boolean } = {}): Promise<SenderContext> {
  const mailbox = await db.companyMailbox.findUnique({ where: { address } });
  if (!mailbox) throw new Error(`No company mailbox ${address}`);
  const password = decryptSecret(mailbox.passwordEnc) || null;
  if (opts.needPassword && !password) throw new Error(`Could not decrypt the password for ${address}.`);
  const displayName = mailbox.displayName || mailbox.label || address.split("@")[0];
  const signatureText = (mailbox.signature || `${displayName}\nOwner, Nxeon\nnxeon.cloud | ${address}`).trim();
  const signatureHtml = (mailbox.signatureHtml?.trim()) || signatureText.split("\n").map((l) => l.replace(/&/g, "&amp;").replace(/</g, "&lt;")).join("<br>");
  const brand = await db.brand.findFirst({ where: { name: "Nxeon" }, select: { name: true, physicalPostalAddress: true } });
  const postalAddress = brand?.physicalPostalAddress?.trim() || "";
  return { address, displayName, signatureHtml, signatureText, brandName: brand?.name ?? "Nxeon", postalAddress, password };
}

export function openSmtp(sender: SenderContext): nodemailer.Transporter {
  if (!sender.password) throw new Error("Sender mailbox password unavailable.");
  return nodemailer.createTransport({
    host: MAIL_SMTP_HOST, port: MAIL_SMTP_PORT, secure: MAIL_SMTP_PORT === 465,
    requireTLS: MAIL_SMTP_PORT !== 465, tls: mailTlsOptions(), auth: { user: sender.address, pass: sender.password },
  });
}

// ---------- THE renderer ----------

export type RenderInput = {
  template: TemplateRow;
  campaign?: { subjectOverride?: string | null; bodyOverride?: string | null } | null;
  recipient: RecipientLike;
  sender: SenderContext;
  claimUrl: string;
  /** CODE templates only: invite fields the standard email shows. */
  invite?: { name: string | null; email: string; ratePct: number | null; allowAnyEmail: boolean } | null;
  inviteExpiresAt?: Date;
};

export function renderOutreachFor(i: RenderInput): RenderedOutreach & { vars: TemplateVars } {
  const unsubscribeUrl = outreachUnsubUrl(i.recipient.email);
  const vars = buildVars(i.recipient, { claimUrl: i.claimUrl, unsubscribeUrl, senderName: i.sender.displayName });
  const footer = { brandName: i.sender.brandName, postalAddress: i.sender.postalAddress, unsubscribeUrl };
  if (i.template.kind === "CODE") {
    const inv = i.invite ?? { name: i.recipient.fullName ?? null, email: i.recipient.email, ratePct: null, allowAnyEmail: false };
    const built = renderCreatorInviteEmail(inv, i.claimUrl, i.inviteExpiresAt ?? new Date(Date.now() + CREATOR_INVITE_TTL_DAYS * 86_400_000));
    return { ...assembleCodeEmail({ subject: built.subject, html: built.html, text: htmlToText(built.html), footer }), vars };
  }
  const c = effectiveContent(i.template, i.campaign);
  const body = renderBody(c.body, vars);
  return {
    ...assembleEmail({
      subject: fillText(c.subject, vars), bodyHtml: body.html, bodyText: body.text,
      signatureHtml: i.sender.signatureHtml, signatureText: i.sender.signatureText, footer,
    }),
    vars,
  };
}

/** The tracking transform applied on send. The preview uses it too (PREVIEW id). */
export function finalizeForSend(r: RenderedOutreach, emailLogId: string): { html: string; text: string; subject: string; links: string[] } {
  const t = injectEmailTracking(r.html, emailLogId);
  return { subject: r.subject, html: t.html, text: r.text, links: t.links };
}

/** Preview/test render: PREVIEW claim token, real sender + footer, tracking placeholder id. */
export function previewOutreach(i: Omit<RenderInput, "claimUrl">) {
  const r = renderOutreachFor({ ...i, claimUrl: creatorClaimUrl(PREVIEW_TOKEN) });
  return { ...finalizeForSend(r, PREVIEW_EMAIL_LOG_ID), vars: r.vars };
}

// ---------- suppression ----------

export async function isOutreachSuppressed(email: string): Promise<string | null> {
  const e = email.trim().toLowerCase();
  const row = await db.outreachSuppression.findUnique({ where: { email: e } });
  if (row) return row.reason;
  // The cold-email engine's GLOBAL list is honoured too (one "never email" truth).
  const g = await db.suppression.findFirst({ where: { scope: "GLOBAL", OR: [{ email: e }, { domain: e.split("@")[1] }] }, select: { id: true } });
  return g ? "UNSUBSCRIBE" : null;
}

export async function suppressEmail(email: string, reason: "UNSUBSCRIBE" | "BOUNCE" | "COMPLAINT" | "MANUAL", source: string, note?: string) {
  const e = email.trim().toLowerCase();
  await db.outreachSuppression.upsert({ where: { email: e }, update: {}, create: { email: e, reason, source, note: note ?? null } });
  // Anything still waiting for this address never goes out.
  const q = await db.outreachQueueItem.findMany({ where: { email: e, status: "QUEUED" }, select: { id: true, campaignId: true } });
  if (q.length) {
    await db.outreachQueueItem.updateMany({ where: { id: { in: q.map((x) => x.id) } }, data: { status: "SKIPPED", error: `suppressed (${reason.toLowerCase()})` } });
    await db.outreachEvent.createMany({ data: q.map((x) => ({ email: e, itemId: x.id, campaignId: x.campaignId, kind: "SUPPRESSED", detail: reason })) });
  }
}

// ---------- the one real send ----------

export type SendDeps = {
  sender: SenderContext;
  smtp: nodemailer.Transporter;
  /** Skip the IMAP Sent-folder copy (tests / sandbox). */
  skipSentCopy?: boolean;
};

export type ItemLike = {
  id: string; email: string; fullName: string; game: string;
  channelUrl: string | null; country: string | null; subscribers: string | null;
};

