/** For CODE templates (already a full HTML document): insert the mandatory footer before </body>. */
export function assembleCodeEmail(a: { subject: string; html: string; text: string; footer: FooterInput }): RenderedOutreach {
  if (!a.footer.postalAddress?.trim()) throw new Error("A physical postal address is required in every outreach email footer.");
  if (!/^https?:\/\//.test(a.footer.unsubscribeUrl || "")) throw new Error("An unsubscribe link is required in every outreach email footer.");
  const f = footerHtml(a.footer);
  const i = a.html.lastIndexOf("</body>");
  const html = i >= 0 ? `${a.html.slice(0, i)}${f}\n${a.html.slice(i)}` : `${a.html}\n${f}`;
  return { subject: a.subject, html, text: [a.text, "", footerText(a.footer)].join("\n").trim() };
}

/** Crude but deterministic html->text for CODE templates' plain-text alternative. */
export function htmlToText(html: string): string {
  return html
    .replace(/<(style|script|head)[\s\S]*?<\/\1>/gi, "")
    .replace(/<a [^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/gi, (_, h, t) => {
      const label = t.replace(/<[^>]+>/g, "").trim();
      return label && label !== h ? `${label} (${h})` : h;
    })
    .replace(/<\/(p|div|tr|h[1-6]|li|table)>/gi, "\n").replace(/<br\s*\/?>/gi, "\n")
    .replace(/<[^>]+>/g, "")
    .replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"').replace(/&#39;/g, "'")
    .replace(/[ \t]+\n/g, "\n").replace(/\n{3,}/g, "\n\n").trim();
}
