/**
 * Outreach campaign engine (plain server module — callers do their own auth).
 * The worker drives `processOutreachTick`; admin server actions call the
 * control functions (all idempotent and CAS-guarded).
 */
import { db } from "../db";
import { getSettingBool } from "../settings";
import {
  canSendNow, nextDelaySeconds, localDayKey, validTimezone, parseDays,
  MIN_INTERVAL_SECONDS, MAX_INTERVAL_SECONDS, type PacingConfig,
} from "./pacing";
import { nextStatus, itemActionAllowed, canEditRecipients, type CampaignAction } from "./state";
import {
  ensureBuiltInTemplates, loadSenderContext, openSmtp, sendOutreachItem, suppressEmail,
  DEFAULT_SENDER, type SenderContext, type TemplateRow,
} from "./service";
import { classifyRows, validEmail, type ExistingSets, type MappedRow, type RowVerdict } from "./csv";

export const KILL_SWITCH_KEY = "outreach_paused_global";
export const STUCK_SENDING_MS = 10 * 60_000;
export const AUTO_PAUSE_AFTER_FAILURES = 3;

export type CampaignRow = NonNullable<Awaited<ReturnType<typeof db.outreachCampaign.findUnique>>>;

export function pacingOf(c: CampaignRow): PacingConfig {
  return {
    intervalSeconds: c.intervalSeconds, jitterPct: c.jitterPct,
    windowStartHour: c.windowStartHour, windowEndHour: c.windowEndHour,
    timezone: c.timezone, days: c.days, dailyCap: c.dailyCap,
    warmupEnabled: c.warmupEnabled, warmupStartCap: c.warmupStartCap, warmupStep: c.warmupStep,
  };
}

// ---------- settings validation ----------

export type CampaignInput = {
  name: string; templateId: string; senderAddress?: string;
  subjectOverride?: string | null; bodyOverride?: string | null;
  intervalSeconds?: number; jitterPct?: number;
  windowStartHour?: number | null; windowEndHour?: number | null;
  timezone?: string; days?: string; dailyCap?: number | null;
  warmupEnabled?: boolean; warmupStartCap?: number; warmupStep?: number;
};

export function validateCampaignInput(i: Partial<CampaignInput>): { error?: string; data?: Record<string, unknown> } {
  const d: Record<string, unknown> = {};
  if (i.name !== undefined) {
    const n = i.name.trim();
    if (!n || n.length > 120) return { error: "Name is required (max 120 characters)." };
    d.name = n;
  }
  if (i.templateId !== undefined) d.templateId = i.templateId;
  if (i.senderAddress !== undefined) {
    if (!validEmail(i.senderAddress.toLowerCase())) return { error: "Pick a valid sender mailbox." };
    d.senderAddress = i.senderAddress.toLowerCase();
  }
  if (i.subjectOverride !== undefined) d.subjectOverride = i.subjectOverride?.trim() || null;
  if (i.bodyOverride !== undefined) d.bodyOverride = i.bodyOverride?.trim() || null;
  if (i.intervalSeconds !== undefined) {
    if (!Number.isFinite(i.intervalSeconds) || i.intervalSeconds < MIN_INTERVAL_SECONDS || i.intervalSeconds > MAX_INTERVAL_SECONDS)
      return { error: `Seconds between emails must be ${MIN_INTERVAL_SECONDS}–${MAX_INTERVAL_SECONDS}.` };
    d.intervalSeconds = Math.round(i.intervalSeconds);
  }
  if (i.jitterPct !== undefined) {
    if (!Number.isFinite(i.jitterPct) || i.jitterPct < 0 || i.jitterPct > 100) return { error: "Jitter must be 0–100%." };
    d.jitterPct = Math.round(i.jitterPct);
  }
  for (const k of ["windowStartHour", "windowEndHour"] as const) {
    const v = i[k];
    if (v !== undefined) {
      if (v !== null && (!Number.isInteger(v) || v < 0 || v > 24)) return { error: "Window hours must be 0–24." };
      d[k] = v;
    }
  }
  if ((i.windowStartHour == null) !== (i.windowEndHour == null) && (i.windowStartHour !== undefined || i.windowEndHour !== undefined))
    return { error: "Set both window start and end hours, or neither." };
  if (i.timezone !== undefined) {
    if (!validTimezone(i.timezone)) return { error: "Unknown timezone (use an IANA name like America/Toronto)." };
    d.timezone = i.timezone;
  }
  if (i.days !== undefined) {
    const days = parseDays(i.days);
    if (days.length === 0) return { error: "Pick at least one send day." };
    d.days = days.join(",");
  }
  if (i.dailyCap !== undefined) {
    if (i.dailyCap !== null && (!Number.isInteger(i.dailyCap) || i.dailyCap < 1 || i.dailyCap > 5000)) return { error: "Daily cap must be 1–5000 (or empty for no cap)." };
    d.dailyCap = i.dailyCap;
  }
  if (i.warmupEnabled !== undefined) d.warmupEnabled = !!i.warmupEnabled;
  for (const k of ["warmupStartCap", "warmupStep"] as const) {
    const v = i[k];
    if (v !== undefined) {
      if (!Number.isInteger(v) || v < (k === "warmupStartCap" ? 1 : 0) || v > 5000) return { error: "Warm-up numbers must be whole numbers (start ≥ 1, step ≥ 0)." };
      d[k] = v;
    }
  }
  return { data: d };
}

export async function createCampaign(input: CampaignInput, createdById: string | null): Promise<{ error?: string; id?: string }> {
  const v = validateCampaignInput(input);
  if (v.error) return { error: v.error };
  const tpl = await db.outreachTemplate.findUnique({ where: { id: input.templateId } });
  if (!tpl || tpl.status !== "ACTIVE") return { error: "Choose an active template." };
  const sender = (input.senderAddress ?? DEFAULT_SENDER).toLowerCase();
  const mb = await db.companyMailbox.findUnique({ where: { address: sender }, select: { id: true } });
  if (!mb) return { error: `No company mailbox ${sender}.` };
  const c = await db.outreachCampaign.create({ data: { ...(v.data as object), name: input.name.trim(), templateId: tpl.id, senderAddress: sender, createdById } as never });
  return { id: c.id };
}

// ---------- recipients ----------

export async function existingSetsFor(emails: string[]): Promise<ExistingSets> {
  const list = [...new Set(emails.filter(Boolean))];
  const [queued, invites, users, supp, gsupp] = await Promise.all([
    db.outreachQueueItem.findMany({ where: { email: { in: list }, status: { in: ["QUEUED", "SENDING", "SENT"] } }, select: { email: true } }),
    // "Already invited" = the invite actually went out (or was claimed). A never-sent DRAFT is fair game.
    db.partnerInvite.findMany({ where: { kind: "CREATOR", email: { in: list }, revokedAt: null, OR: [{ lastSentAt: { not: null } }, { acceptedAt: { not: null } }] }, select: { email: true } }),
    db.user.findMany({ where: { email: { in: list }, referralPartner: { isNot: null } }, select: { email: true } }),
    db.outreachSuppression.findMany({ where: { email: { in: list } }, select: { email: true } }),
    db.suppression.findMany({ where: { scope: "GLOBAL", email: { in: list } }, select: { email: true } }),
  ]);
  const lower = (r: { email: string | null }[]) => new Set(r.map((x) => (x.email ?? "").toLowerCase()));
  return { queued: lower(queued), invited: lower(invites), partners: lower(users), suppressed: new Set([...lower(supp), ...lower(gsupp)]) };
}

export async function previewImport(rows: MappedRow[]) {
  const sets = await existingSetsFor(rows.map((r) => r.email));
  return classifyRows(rows, sets);
}

/** Add the OK rows of a classified import to a campaign. Re-classifies server-side (never trusts the client). */
export async function addRecipients(campaignId: string, rows: MappedRow[], actorId: string | null): Promise<{ error?: string; added?: number; skipped?: Record<string, number> }> {
  const c = await db.outreachCampaign.findUnique({ where: { id: campaignId } });
  if (!c) return { error: "Campaign not found." };
  if (!canEditRecipients(c.status)) return { error: `A ${c.status.toLowerCase()} campaign can't take new recipients — reopen it first.` };
  const classified = await previewImport(rows);
  const ok = classified.filter((x) => x.verdict === "ok");
  const skipped: Record<string, number> = {};
  for (const x of classified) if (x.verdict !== "ok") skipped[x.verdict] = (skipped[x.verdict] ?? 0) + 1;
  if (ok.length === 0) return { added: 0, skipped };
  const last = await db.outreachQueueItem.aggregate({ where: { campaignId }, _max: { sortOrder: true } });
  let order = (last._max.sortOrder ?? 0) + 1;
  const tpl = c.templateId ? await db.outreachTemplate.findUnique({ where: { id: c.templateId }, select: { name: true } }) : null;
  const created = await db.$transaction(ok.map((x) => db.outreachQueueItem.create({
    data: {
      campaignId, email: x.row.email, fullName: x.row.name || "there", game: x.row.game || "your game",
      channelUrl: x.row.channel || null, country: x.row.country || null, subscribers: x.row.subscribers || null,
      sortOrder: order++, templateName: tpl?.name ?? null,
    },
    select: { id: true, email: true },
  })));
  await db.outreachEvent.createMany({ data: created.map((x) => ({ campaignId, itemId: x.id, email: x.email, kind: "QUEUED", detail: `added to ${c.name}` })) });
  await db.auditLog.create({ data: { userId: actorId, action: "outreach.recipients_added", detail: `campaign=${campaignId} added=${created.length}` } });
  return { added: created.length, skipped };
}

// ---------- campaign controls ----------

export async function controlCampaign(campaignId: string, action: CampaignAction, actorId: string | null): Promise<{ error?: string; status?: string }> {
  const c = await db.outreachCampaign.findUnique({ where: { id: campaignId } });
  if (!c) return { error: "Campaign not found." };
  const to = nextStatus(c.status, action);
  if (!to) return { error: `Can't ${action} a ${c.status.toLowerCase()} campaign.` };
  if (action === "start") {
    const queued = await db.outreachQueueItem.count({ where: { campaignId, status: "QUEUED" } });
    if (queued === 0) return { error: "Add recipients before starting." };
    if (!c.templateId) return { error: "Choose a template before starting." };
    const sender = await loadSenderContext(c.senderAddress).catch((e: Error) => e);
    if (sender instanceof Error) return { error: sender.message };
    if (!sender.postalAddress) return { error: "The brand has no postal address set — every email must carry one (CAN-SPAM). Set it under Brands." };
  }
  // CAS on the current status so a double-click / racing worker can't double-apply.
  const data: Record<string, unknown> = { status: to, pauseReason: to === "PAUSED" ? (action === "pause" ? null : c.pauseReason) : null };
  if (to === "RUNNING") { data.startedAt = c.startedAt ?? new Date(); data.nextSendAt = null; }
  if (to === "COMPLETED" || to === "CANCELLED") data.completedAt = new Date();
  if (action === "reopen") data.completedAt = null;
  const r = await db.outreachCampaign.updateMany({ where: { id: campaignId, status: c.status }, data: data as never });
  if (r.count !== 1) return { error: "The campaign changed state meanwhile — refresh and retry." };
  await db.auditLog.create({ data: { userId: actorId, action: `outreach.campaign_${action}`, detail: `campaign=${campaignId} ${c.status}->${to}` } });
  return { status: to };
}

export async function deleteCampaign(campaignId: string, actorId: string | null): Promise<{ error?: string }> {
  const c = await db.outreachCampaign.findUnique({ where: { id: campaignId } });
  if (!c) return { error: "Campaign not found." };
  if (c.status === "RUNNING") return { error: "Pause or stop the campaign before deleting it." };
  if (c.isLegacyDefault) return { error: "The legacy queue campaign holds the original send history and can't be deleted." };
  const sending = await db.outreachQueueItem.count({ where: { campaignId, status: "SENDING" } });
  if (sending) return { error: "An email is being sent right now — try again in a moment." };
  await db.outreachCampaign.delete({ where: { id: campaignId } });
  await db.auditLog.create({ data: { userId: actorId, action: "outreach.campaign_delete", detail: `campaign=${campaignId} name=${c.name}` } });
  return {};
}

export async function updateCampaignSettings(campaignId: string, input: Partial<CampaignInput>, actorId: string | null): Promise<{ error?: string }> {
  const c = await db.outreachCampaign.findUnique({ where: { id: campaignId } });
  if (!c) return { error: "Campaign not found." };
  if (c.status === "COMPLETED" || c.status === "CANCELLED") return { error: "Reopen the campaign to edit it." };
  const v = validateCampaignInput(input);
  if (v.error) return { error: v.error };
  if (input.templateId) {
    const t = await db.outreachTemplate.findUnique({ where: { id: input.templateId } });
    if (!t || t.status !== "ACTIVE") return { error: "Choose an active template." };
  }
  if (input.senderAddress) {
    const mb = await db.companyMailbox.findUnique({ where: { address: input.senderAddress.toLowerCase() }, select: { id: true } });
    if (!mb) return { error: "That mailbox doesn't exist." };
  }
  await db.outreachCampaign.update({ where: { id: campaignId }, data: v.data as never });
  await db.auditLog.create({ data: { userId: actorId, action: "outreach.campaign_update", detail: `campaign=${campaignId} keys=${Object.keys(v.data ?? {}).join(",")}` } });
  return {};
}

// ---------- per-recipient controls ----------

export type ItemAction = "skip" | "unskip" | "retry" | "remove" | "edit" | "top" | "up" | "down";

export async function itemControl(
  itemId: string, action: ItemAction, actorId: string | null,
  edit?: { email?: string; fullName?: string; game?: string; channelUrl?: string; country?: string; subscribers?: string },
): Promise<{ error?: string }> {
  const it = await db.outreachQueueItem.findUnique({ where: { id: itemId } });
  if (!it) return { error: "Recipient not found." };
  const ev = (kind: string, detail?: string) => db.outreachEvent.create({ data: { campaignId: it.campaignId, itemId, email: it.email, kind, detail: detail ?? null } });
  if (action === "top" || action === "up" || action === "down") {
    if (it.status !== "QUEUED" || !it.campaignId) return { error: "Only queued recipients can be reordered." };
    const q = await db.outreachQueueItem.findMany({ where: { campaignId: it.campaignId, status: "QUEUED" }, orderBy: [{ sortOrder: "asc" }, { createdAt: "asc" }], select: { id: true } });
    const ids = q.map((x) => x.id);
    const i = ids.indexOf(itemId);
    ids.splice(i, 1);
    ids.splice(action === "top" ? 0 : action === "up" ? Math.max(0, i - 1) : Math.min(ids.length, i + 1), 0, itemId);
    await db.$transaction(ids.map((id, n) => db.outreachQueueItem.update({ where: { id }, data: { sortOrder: n + 1 } })));
    return {};
  }
  const gate = action === "retry" ? "retry" : action === "unskip" ? "unskip" : action;
  if (!itemActionAllowed(it.status, gate as never)) return { error: `Can't ${action} a recipient that is ${it.status.toLowerCase()}.` };
  if (action === "skip") {
    const r = await db.outreachQueueItem.updateMany({ where: { id: itemId, status: it.status }, data: { status: "SKIPPED", error: "skipped by admin" } });
    if (r.count !== 1) return { error: "That recipient just changed state — refresh." };
    await ev("SKIPPED", "skipped by admin");
  } else if (action === "unskip" || action === "retry") {
    const r = await db.outreachQueueItem.updateMany({ where: { id: itemId, status: it.status }, data: { status: "QUEUED", error: null } });
    if (r.count !== 1) return { error: "That recipient just changed state — refresh." };
    await ev("RETRIED", action === "retry" ? "re-queued after failure" : "un-skipped");
  } else if (action === "remove") {
    await db.outreachQueueItem.delete({ where: { id: itemId } });
  } else if (action === "edit" && edit) {
    const data: Record<string, string | null> = {};
    if (edit.email !== undefined) {
      const e = edit.email.trim().toLowerCase();
      if (!validEmail(e)) return { error: "That email address isn't valid." };
      data.email = e;
    }
    if (edit.fullName !== undefined) data.fullName = edit.fullName.trim().slice(0, 120) || "there";
    if (edit.game !== undefined) data.game = edit.game.trim().slice(0, 80) || "your game";
    if (edit.channelUrl !== undefined) data.channelUrl = edit.channelUrl.trim().slice(0, 300) || null;
    if (edit.country !== undefined) data.country = edit.country.trim().slice(0, 80) || null;
    if (edit.subscribers !== undefined) data.subscribers = edit.subscribers.trim().slice(0, 40) || null;
    await db.outreachQueueItem.update({ where: { id: itemId }, data });
    await ev("EDITED", Object.keys(data).join(","));
  }
  await db.auditLog.create({ data: { userId: actorId, action: `outreach.item_${action}`, detail: `item=${itemId} email=${it.email}` } });
  return {};
}

// ---------- legacy migration ----------

/**
 * The 97-row CSV queue predates campaigns. Any item without a campaign is
 * adopted into ONE default "Legacy creator queue" campaign that reproduces the
 * old behaviour exactly (builtin outreach template, santino@, 60 s apart, no
 * window/cap). Idempotent; safe to run every tick.
 */
export async function adoptLegacyQueue(): Promise<{ adopted: number }> {
  const orphans = await db.outreachQueueItem.count({ where: { campaignId: null } });
  if (orphans === 0) return { adopted: 0 };
  const { outreachId } = await ensureBuiltInTemplates();
  let camp = await db.outreachCampaign.findFirst({ where: { isLegacyDefault: true } });
  if (!camp) {
    const queued = await db.outreachQueueItem.count({ where: { campaignId: null, status: "QUEUED" } });
    camp = await db.outreachCampaign.create({
      data: {
        name: "Legacy creator queue (CSV uploads)", isLegacyDefault: true, templateId: outreachId,
        senderAddress: DEFAULT_SENDER, intervalSeconds: 60, jitterPct: 0,
        status: queued > 0 ? "RUNNING" : "COMPLETED", startedAt: new Date(),
      },
    });
  }
  const tpl = await db.outreachTemplate.findUnique({ where: { id: camp.templateId ?? outreachId }, select: { name: true } });
  const r = await db.outreachQueueItem.updateMany({ where: { campaignId: null }, data: { campaignId: camp.id, templateName: tpl?.name ?? null } });
  // Re-activate a campaign that had finished if new orphans (e.g. an old uploader) arrive.
  if (camp.status === "COMPLETED") await db.outreachCampaign.update({ where: { id: camp.id }, data: { status: "RUNNING", completedAt: null } });
  // Give each already-sent legacy row a timeline entry (idempotent via dedupeKey).
  const sent = await db.outreachQueueItem.findMany({ where: { campaignId: camp.id, status: "SENT" }, select: { id: true, email: true, sentAt: true } });
  if (sent.length) {
    await db.outreachEvent.createMany({
      data: sent.map((s) => ({ campaignId: camp!.id, itemId: s.id, email: s.email, kind: "SENT", detail: "migrated from legacy queue", dedupeKey: `legacy-sent:${s.id}`, at: s.sentAt ?? new Date() })),
      skipDuplicates: true,
    });
  }
  return { adopted: r.count };
}

// ---------- the worker tick ----------

let tickInFlight = false;
const senderCache = new Map<string, { at: number; ctx: SenderContext }>();

async function senderFor(address: string): Promise<SenderContext> {
  const hit = senderCache.get(address);
  if (hit && Date.now() - hit.at < 5 * 60_000) return hit.ctx;
  const ctx = await loadSenderContext(address, { needPassword: true });
  senderCache.set(address, { at: Date.now(), ctx });
  return ctx;
}

export type TickDeps = {
  now?: () => Date;
  rand?: () => number;
  /** Test seam: replaces SMTP + sender lookup. */
  transport?: (sender: SenderContext) => import("nodemailer").Transporter;
  skipSentCopy?: boolean;
};

/** In a sandbox/dev run the real mail server must NEVER be touched. */
async function defaultTransport(sender: SenderContext) {
  if (process.env.NXEON_SANDBOX === "1" || process.env.OUTREACH_DRY_RUN === "1") {
    const nm = (await import("nodemailer")).default;
    return nm.createTransport({ jsonTransport: true });
  }
  return openSmtp(sender);
}

export async function recoverStuckSending(now = new Date()): Promise<number> {
  const stuck = await db.outreachQueueItem.findMany({
    where: { status: "SENDING", lastAttemptAt: { lt: new Date(now.getTime() - STUCK_SENDING_MS) } },
    select: { id: true, email: true, campaignId: true },
  });
  for (const s of stuck) {
    // NOT re-queued automatically: the worker may have died AFTER the SMTP accept, and a
    // blind retry would double-email a creator. A human checks Sent, then hits Retry.
    const r = await db.outreachQueueItem.updateMany({ where: { id: s.id, status: "SENDING" }, data: { status: "FAILED", error: "interrupted mid-send (worker restarted) — check the Sent folder before retrying" } });
    if (r.count === 1) await db.outreachEvent.create({ data: { campaignId: s.campaignId, itemId: s.id, email: s.email, kind: "FAILED", detail: "interrupted mid-send" } });
  }
  return stuck.length;
}

export type TickResult = { sent: number; failed: number; skipped: number; note?: string };

/**
 * One scheduler pass. Single-flight in-process (tickInFlight) and per-item CAS in
 * the DB, so even two worker processes could never send the same row. At most
 * one email per sender mailbox per pass.
 */
export async function processOutreachTick(deps: TickDeps = {}): Promise<TickResult> {
  const res: TickResult = { sent: 0, failed: 0, skipped: 0 };
  if (tickInFlight) return { ...res, note: "already running" };
  tickInFlight = true;
  try {
    const now = deps.now?.() ?? new Date();
    if (await getSettingBool(KILL_SWITCH_KEY, false)) return { ...res, note: "global kill switch on" };
    await adoptLegacyQueue();
    await recoverStuckSending(now);

    const campaigns = await db.outreachCampaign.findMany({ where: { status: "RUNNING" }, orderBy: { createdAt: "asc" } });
    const usedSenders = new Set<string>();
    for (const c of campaigns) {
      if (usedSenders.has(c.senderAddress)) continue;
      const pacing = pacingOf(c);
      const sentRows = await db.outreachQueueItem.findMany({ where: { campaignId: c.id, status: "SENT", sentAt: { gte: new Date(now.getTime() - 36 * 3600_000) } }, select: { sentAt: true } });
      const today = localDayKey(now, c.timezone);
      const sentToday = sentRows.filter((r) => r.sentAt && localDayKey(r.sentAt, c.timezone) === today).length;
      const decision = canSendNow(pacing, { nextSendAt: c.nextSendAt, startedAt: c.startedAt, sentToday }, now);
      if (!decision.ok) continue;

      const next = await db.outreachQueueItem.findFirst({ where: { campaignId: c.id, status: "QUEUED" }, orderBy: [{ sortOrder: "asc" }, { createdAt: "asc" }] });
      if (!next) {
        const inflight = await db.outreachQueueItem.count({ where: { campaignId: c.id, status: "SENDING" } });
        if (inflight === 0) await controlCampaign(c.id, "complete", null);
        continue;
      }
      const claim = await db.outreachQueueItem.updateMany({
        where: { id: next.id, status: "QUEUED" },
        data: { status: "SENDING", attempts: { increment: 1 }, lastAttemptAt: now },
      });
      if (claim.count !== 1) continue; // someone else won it
      usedSenders.add(c.senderAddress);
      const outcome = await sendClaimed(c, next.id, deps, now);
      res[outcome]++;
      // Advance the persisted pacing clock whatever the outcome (never hammer on failure).
      const delay = nextDelaySeconds(c.intervalSeconds, c.jitterPct, deps.rand);
      await db.outreachCampaign.update({ where: { id: c.id }, data: { nextSendAt: new Date(now.getTime() + delay * 1000), ...(outcome === "sent" ? { lastSentAt: now } : {}) } });
      if (outcome === "failed") await maybeAutoPause(c.id);
    }
    return res;
  } finally {
    tickInFlight = false;
  }
}

async function sendClaimed(c: CampaignRow, itemId: string, deps: TickDeps, now: Date): Promise<"sent" | "failed" | "skipped"> {
  const item = await db.outreachQueueItem.findUniqueOrThrow({ where: { id: itemId } });
  const fail = async (error: string, status: "FAILED" | "SKIPPED" = "FAILED") => {
    await db.outreachQueueItem.update({ where: { id: itemId }, data: { status, error } });
    await db.outreachEvent.create({ data: { campaignId: c.id, itemId, email: item.email, kind: status === "FAILED" ? "FAILED" : "SKIPPED", detail: error.slice(0, 300) } });
    console.log(`[outreach] ${status.toLowerCase()} -> ${item.email}: ${error}`);
    return status === "FAILED" ? ("failed" as const) : ("skipped" as const);
  };
  try {
    const tpl = c.templateId ? await db.outreachTemplate.findUnique({ where: { id: c.templateId } }) : null;
    if (!tpl) return await fail("campaign has no template");
    const sender = await senderFor(c.senderAddress);
    if (!sender.postalAddress) return await fail("brand has no postal address (CAN-SPAM)");
    const smtp = deps.transport ? deps.transport(sender) : await defaultTransport(sender);
    const r = await sendOutreachItem({ sender, smtp, skipSentCopy: deps.skipSentCopy ?? (process.env.NXEON_SANDBOX === "1" || process.env.OUTREACH_DRY_RUN === "1") }, tpl, c, item);
    if (!r.ok) return await fail(r.error, r.skipped ? "SKIPPED" : "FAILED");
    await db.outreachQueueItem.update({ where: { id: itemId }, data: { status: "SENT", sentAt: now, error: null, messageId: r.messageId, emailLogId: r.emailLogId, templateName: tpl.name } });
    await db.outreachEvent.create({ data: { campaignId: c.id, itemId, email: item.email, kind: "SENT", detail: tpl.name } });
    console.log(`[outreach] sent -> ${item.email} (${c.name})`);
    return "sent";
  } catch (e) {
    return await fail(e instanceof Error ? e.message : String(e));
  }
}

async function maybeAutoPause(campaignId: string) {
  const last = await db.outreachQueueItem.findMany({
    where: { campaignId, lastAttemptAt: { not: null }, status: { in: ["SENT", "FAILED", "SKIPPED"] } },
    orderBy: { lastAttemptAt: "desc" }, take: AUTO_PAUSE_AFTER_FAILURES, select: { status: true },
  });
  if (last.length === AUTO_PAUSE_AFTER_FAILURES && last.every((x) => x.status === "FAILED")) {
    const r = await db.outreachCampaign.updateMany({ where: { id: campaignId, status: "RUNNING" }, data: { status: "PAUSED", pauseReason: `auto-paused after ${AUTO_PAUSE_AFTER_FAILURES} consecutive send failures` } });
    if (r.count === 1) await db.auditLog.create({ data: { userId: null, action: "outreach.campaign_auto_pause", detail: `campaign=${campaignId}` } });
  }
}

/** Send exactly one recipient immediately (manual "send next now" / a specific row), ignoring pacing. */
export async function sendItemNow(itemId: string, actorId: string | null, deps: TickDeps = {}): Promise<{ error?: string; ok?: boolean }> {
  if (await getSettingBool(KILL_SWITCH_KEY, false)) return { error: "The global outreach kill switch is on." };
  const it = await db.outreachQueueItem.findUnique({ where: { id: itemId }, include: { campaign: true } });
  if (!it || !it.campaign) return { error: "Recipient not found." };
  if (it.campaign.status === "COMPLETED" || it.campaign.status === "CANCELLED") return { error: "Reopen the campaign first." };
  if (!itemActionAllowed(it.status, "send-now")) return { error: `Can't send a recipient that is ${it.status.toLowerCase()}.` };
  const claim = await db.outreachQueueItem.updateMany({ where: { id: itemId, status: it.status }, data: { status: "SENDING", attempts: { increment: 1 }, lastAttemptAt: new Date() } });
  if (claim.count !== 1) return { error: "That recipient just changed state — refresh." };
  const outcome = await sendClaimed(it.campaign, itemId, deps, new Date());
  await db.auditLog.create({ data: { userId: actorId, action: "outreach.send_now", detail: `item=${itemId} email=${it.email} outcome=${outcome}` } });
  if (outcome !== "sent") {
    const fresh = await db.outreachQueueItem.findUnique({ where: { id: itemId }, select: { error: true } });
    return { error: fresh?.error ?? "Send failed." };
  }
  return { ok: true };
}

// ---------- stats ----------

export type CampaignStats = {
  total: number; queued: number; sending: number; sent: number; failed: number; skipped: number;
  opened: number; clicked: number; claimed: number; replied: number; bounced: number; unsubscribed: number;
};

export async function campaignStats(campaignId: string): Promise<CampaignStats> {
  const items = await db.outreachQueueItem.findMany({ where: { campaignId }, select: { email: true, status: true, emailLogId: true } });
  const s: CampaignStats = { total: items.length, queued: 0, sending: 0, sent: 0, failed: 0, skipped: 0, opened: 0, clicked: 0, claimed: 0, replied: 0, bounced: 0, unsubscribed: 0 };
  for (const i of items) {
    if (i.status === "QUEUED") s.queued++; else if (i.status === "SENDING") s.sending++; else if (i.status === "SENT") s.sent++; else if (i.status === "FAILED") s.failed++; else if (i.status === "SKIPPED") s.skipped++;
  }
  const sentEmails = items.filter((i) => i.status === "SENT").map((i) => i.email);
  const logIds = items.map((i) => i.emailLogId).filter((x): x is string => !!x);
  const [logs, claims, evs] = await Promise.all([
    logIds.length ? db.emailLog.findMany({ where: { id: { in: logIds } }, select: { openedAt: true, clickedAt: true } }) : Promise.resolve([]),
    sentEmails.length ? db.partnerInvite.findMany({ where: { kind: "CREATOR", email: { in: sentEmails }, acceptedAt: { not: null } }, select: { email: true } }) : Promise.resolve([]),
    db.outreachEvent.findMany({ where: { campaignId, kind: { in: ["REPLY", "BOUNCE", "UNSUBSCRIBE"] } }, select: { kind: true, email: true } }),
  ]);
  s.opened = logs.filter((l) => l.openedAt).length;
  s.clicked = logs.filter((l) => l.clickedAt).length;
  s.claimed = new Set(claims.map((c) => c.email.toLowerCase())).size;
  const uniq = (k: string) => new Set(evs.filter((e) => e.kind === k).map((e) => e.email)).size;
  s.replied = uniq("REPLY"); s.bounced = uniq("BOUNCE"); s.unsubscribed = uniq("UNSUBSCRIBE");
  return s;
}

