/**
 * Reply / bounce / unsubscribe detection. READ-ONLY: the INBOX is opened with an
 * EXAMINE-style readOnly lock (no \Seen flags set, nothing moved or deleted).
 * Results become OutreachEvent rows (idempotent via dedupeKey), bounces and
 * unsubscribes also go on the suppression list.
 */
import { db } from "../db";
import { createImapClient, parseMessage } from "../mail/imap";
import { classifyInbound, type InboundMessage } from "./inbound";
import { suppressEmail, loadSenderContext } from "./service";

/** Abstraction so tests can feed fixtures instead of a live IMAP server. */
export type InboxFetcher = (since: Date) => Promise<InboundMessage[]>;

export function imapFetcher(address: string, password: string): InboxFetcher {
  return async (since) => {
    const client = createImapClient({ address, password });
    await client.connect();
    const out: InboundMessage[] = [];
    try {
      const lock = await client.getMailboxLock("INBOX", { readOnly: true });
      try {
        const uids = (await client.search({ since }, { uid: true })) || [];
        for (const uid of (uids as number[]).slice(-500)) {
          const m = await client.fetchOne(String(uid), { uid: true, envelope: true, source: { maxLength: 60_000 } } as never, { uid: true });
          if (!m || !m.source) continue;
          const p = await parseMessage(m.source as Buffer);
          let text = p.text || "";
          for (const a of p.attachments || []) {
            if (/delivery-status|rfc822/i.test(a.contentType || "") && a.content) text += `\n${a.content.toString("utf8").slice(0, 6000)}`;
          }
          const f = p.from?.value?.[0];
          out.push({
            uid, messageId: p.messageId ?? null, inReplyTo: p.inReplyTo ?? null,
            fromAddress: (f?.address || "").toLowerCase(), fromName: f?.name,
            subject: p.subject || "", date: p.date || new Date(), text: text.slice(0, 8000),
          });
        }
      } finally { lock.release(); }
    } finally {
      try { await client.logout(); } catch { try { client.close(); } catch { /* gone */ } }
    }
    return out;
  };
}

export type ScanResult = { scanned: number; replies: number; bounces: number; unsubscribes: number };

export async function scanOutreachInbox(senderAddress: string, opts: { fetcher?: InboxFetcher; lookbackDays?: number; now?: Date } = {}): Promise<ScanResult> {
  const now = opts.now ?? new Date();
  const since = new Date(now.getTime() - (opts.lookbackDays ?? 14) * 86_400_000);
  const items = await db.outreachQueueItem.findMany({
    where: { status: "SENT", sentAt: { gte: new Date(now.getTime() - 90 * 86_400_000) }, campaign: { senderAddress } },
    select: { id: true, email: true, campaignId: true },
  });
  const byEmail = new Map(items.map((i) => [i.email.toLowerCase(), i]));
  const res: ScanResult = { scanned: 0, replies: 0, bounces: 0, unsubscribes: 0 };
  if (byEmail.size === 0) return res;

  let fetcher = opts.fetcher;
  if (!fetcher) {
    const sender = await loadSenderContext(senderAddress, { needPassword: true });
    fetcher = imapFetcher(senderAddress, sender.password!);
  }
  const msgs = await fetcher(since);
  res.scanned = msgs.length;
  const recipients = new Set(byEmail.keys());
  for (const m of msgs) {
    const c = classifyInbound(m, recipients);
    if (!c) continue;
    const it = byEmail.get(c.email);
    const dedupeKey = `${c.kind.toLowerCase()}:${m.messageId || `${senderAddress}:${m.uid}:${m.date.toISOString()}`}`;
    const exists = await db.outreachEvent.findUnique({ where: { dedupeKey }, select: { id: true } });
    if (exists) continue;
    await db.outreachEvent.create({ data: { campaignId: it?.campaignId ?? null, itemId: it?.id ?? null, email: c.email, kind: c.kind, detail: c.detail, dedupeKey, at: m.date } });
    if (c.kind === "REPLY") res.replies++;
    if (c.kind === "BOUNCE") { res.bounces++; await suppressEmail(c.email, "BOUNCE", "inbox-scan", c.detail); }
    if (c.kind === "UNSUBSCRIBE") { res.unsubscribes++; await suppressEmail(c.email, "UNSUBSCRIBE", "inbox-reply", c.detail); }
  }
  return res;
}

/** Scan every sender mailbox that has outreach history. Never throws. */
export async function scanAllOutreachInboxes(): Promise<void> {
  const senders = await db.outreachCampaign.findMany({ distinct: ["senderAddress"], select: { senderAddress: true } });
  for (const s of senders) {
    try {
      const r = await scanOutreachInbox(s.senderAddress);
      if (r.replies || r.bounces || r.unsubscribes) console.log(`[outreach-scan] ${s.senderAddress}: ${r.replies} replies, ${r.bounces} bounces, ${r.unsubscribes} unsubscribes`);
    } catch (e) {
      console.error(`[outreach-scan] ${s.senderAddress} failed:`, e instanceof Error ? e.message : e);
    }
  }
}
