"use server";

/**
 * Admin server actions for the outreach campaign system (/admin/partners/outreach).
 * Every action is gated by requireArea("billing") (same as the rest of the
 * Partners admin), audit-logged where it mutates, and returns {error} rather
 * than throwing for expected failures.
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireArea } from "./rbac";
import { setSetting } from "./settings";
import { creatorClaimUrl, PREVIEW_TOKEN } from "./partner-invite-core";
import {
  addRecipients, controlCampaign, createCampaign, deleteCampaign, itemControl, previewImport, sendItemNow,
  updateCampaignSettings, KILL_SWITCH_KEY, type CampaignInput, type ItemAction,
} from "./outreach/campaign-core";
import { applyMapping, readGrid, suggestMapping, summarize, type ColumnMapping, type MappedRow } from "./outreach/csv";
import {
  DEFAULT_SENDER, effectiveContent, ensureBuiltInTemplates, loadSenderContext, openSmtp, previewOutreach, suppressEmail,
  type TemplateRow,
} from "./outreach/service";
import { findUnknownVars, SAMPLE_RECIPIENT, TEMPLATE_VARIABLES } from "./outreach/render";
import { scanOutreachInbox } from "./outreach/inbox-scan";
import type { CampaignAction } from "./outreach/state";

const PAGE = "/admin/partners";
const refresh = (extra?: string) => { revalidatePath(PAGE); revalidatePath(`${PAGE}/outreach`); if (extra) revalidatePath(extra); };

// ---------- CSV import ----------

export async function analyzeOutreachCsv(csv: string) {
  await requireArea("billing");
  if (csv.length > 5_000_000) return { error: "That file is too large (5 MB max)." };
  const g = readGrid(csv);
  if (g.error) return { error: g.error };
  return { headers: g.headers, mapping: suggestMapping(g.headers), sample: g.rows.slice(0, 4), total: g.rows.length };
}

function mapped(csv: string, mapping: ColumnMapping): { rows?: MappedRow[]; error?: string } {
  const g = readGrid(csv);
  if (g.error) return { error: g.error };
  if (mapping.email == null || mapping.email < 0) return { error: "Map the Email column first." };
  const rows = applyMapping(g.rows, mapping);
  if (rows.length === 0) return { error: "No data rows found." };
  if (rows.length > 20_000) return { error: "Too many rows (20,000 max per upload)." };
  return { rows };
}

export async function previewOutreachImport(csv: string, mapping: ColumnMapping) {
  await requireArea("billing");
  const m = mapped(csv, mapping);
  if (m.error) return { error: m.error };
  const classified = await previewImport(m.rows!);
  return {
    counts: summarize(classified),
    problems: classified.filter((x) => x.verdict !== "ok").slice(0, 100).map((x) => ({ line: x.row.line, email: x.row.email, verdict: x.verdict })),
    total: classified.length,
  };
}

export async function importOutreachCsv(campaignId: string, csv: string, mapping: ColumnMapping) {
  const user = await requireArea("billing");
  const m = mapped(csv, mapping);
  if (m.error) return { error: m.error };
  const r = await addRecipients(String(campaignId), m.rows!, user.id);
  refresh(`${PAGE}/outreach/${campaignId}`);
  return r;
}

// ---------- campaigns ----------

export async function createOutreachCampaign(input: CampaignInput): Promise<{ error?: string; id?: string }> {
  const user = await requireArea("billing");
  await ensureBuiltInTemplates();
  const r = await createCampaign(input, user.id);
  if (r.id) await db.auditLog.create({ data: { userId: user.id, action: "outreach.campaign_create", detail: `campaign=${r.id} name=${input.name}` } });
  refresh();
  return r;
}

export async function updateOutreachCampaign(id: string, input: Partial<CampaignInput>) {
  const user = await requireArea("billing");
  const r = await updateCampaignSettings(String(id), input, user.id);
  refresh(`${PAGE}/outreach/${id}`);
  return r;
}

export async function controlOutreachCampaign(id: string, action: CampaignAction) {
  const user = await requireArea("billing");
  const r = await controlCampaign(String(id), action, user.id);
  refresh(`${PAGE}/outreach/${id}`);
  return r;
}

export async function deleteOutreachCampaign(id: string) {
  const user = await requireArea("billing");
  const r = await deleteCampaign(String(id), user.id);
  refresh();
  return r;
}

export async function outreachItemAction(
  itemId: string, action: ItemAction,
  edit?: { email?: string; fullName?: string; game?: string; channelUrl?: string; country?: string; subscribers?: string },
) {
  const user = await requireArea("billing");
  const it = await db.outreachQueueItem.findUnique({ where: { id: String(itemId) }, select: { campaignId: true } });
  const r = await itemControl(String(itemId), action, user.id, edit);
  refresh(it?.campaignId ? `${PAGE}/outreach/${it.campaignId}` : undefined);
  return r;
}

export async function outreachSendNow(itemId: string) {
  const user = await requireArea("billing");
  const it = await db.outreachQueueItem.findUnique({ where: { id: String(itemId) }, select: { campaignId: true } });
  const r = await sendItemNow(String(itemId), user.id);
  refresh(it?.campaignId ? `${PAGE}/outreach/${it.campaignId}` : undefined);
  return r;
}

/** "Send next now": the first queued recipient of a RUNNING/PAUSED campaign, ignoring pacing. */
export async function outreachSendNextNow(campaignId: string) {
  const user = await requireArea("billing");
  const next = await db.outreachQueueItem.findFirst({ where: { campaignId: String(campaignId), status: "QUEUED" }, orderBy: [{ sortOrder: "asc" }, { createdAt: "asc" }], select: { id: true } });
  if (!next) return { error: "Nothing queued." };
  const r = await sendItemNow(next.id, user.id);
  refresh(`${PAGE}/outreach/${campaignId}`);
  return r;
}

export async function setOutreachKillSwitch(on: boolean) {
  const user = await requireArea("billing");
  await setSetting(KILL_SWITCH_KEY, on ? "true" : "false");
  await db.auditLog.create({ data: { userId: user.id, action: "outreach.kill_switch", detail: on ? "ON" : "OFF" } });
  refresh();
  return { ok: true };
}

// ---------- templates ----------

function checkTemplate(subject: string, body: string, kind: string): string | null {
  if (!subject.trim() || subject.length > 300) return "Subject is required (max 300 characters).";
  if (kind === "MARKDOWN" && !body.trim()) return "The email body is empty.";
  if (body.length > 50_000) return "The body is too long.";
  const unknown = findUnknownVars(`${subject}\n${body}`);
  if (unknown.length) return `Unknown variable${unknown.length > 1 ? "s" : ""}: ${unknown.map((u) => `{{${u}}}`).join(", ")}. Available: ${TEMPLATE_VARIABLES.map((v) => `{{${v}}}`).join(" ")}`;
  return null;
}

export async function saveOutreachTemplate(input: { id?: string; name: string; subject: string; body: string }): Promise<{ error?: string; id?: string }> {
  const user = await requireArea("billing");
  const name = input.name.trim();
  if (!name || name.length > 120) return { error: "Name is required (max 120 characters)." };
  const err = checkTemplate(input.subject, input.body, "MARKDOWN");
  if (err) return { error: err };
  if (input.id) {
    const t = await db.outreachTemplate.findUnique({ where: { id: input.id } });
    if (!t) return { error: "Template not found." };
