export async function outreachRecipientTimeline(email: string) {
  await requireArea("billing");
  const e = email.trim().toLowerCase();
  const [events, logs] = await Promise.all([
    db.outreachEvent.findMany({ where: { email: e }, orderBy: { at: "asc" }, take: 200 }),
    db.emailLog.findMany({ where: { toEmail: e, template: { startsWith: "creator_partner_invite" } }, orderBy: { createdAt: "asc" }, select: { createdAt: true, openedAt: true, openCount: true, clickedAt: true, clickCount: true, status: true } }),
  ]);
  const rows: { at: Date; kind: string; detail: string | null }[] = events.map((x) => ({ at: x.at, kind: x.kind, detail: x.detail }));
  for (const l of logs) {
    if (l.openedAt) rows.push({ at: l.openedAt, kind: "OPENED", detail: `${l.openCount}×` });
    if (l.clickedAt) rows.push({ at: l.clickedAt, kind: "CLICKED", detail: `${l.clickCount}×` });
  }
  const inv = await db.partnerInvite.findFirst({ where: { kind: "CREATOR", email: e, acceptedAt: { not: null } }, select: { acceptedAt: true } });
  if (inv?.acceptedAt) rows.push({ at: inv.acceptedAt, kind: "CLAIMED", detail: null });
  rows.sort((a, b) => a.at.getTime() - b.at.getTime());
  return { rows: rows.map((r) => ({ ...r, at: r.at.toISOString() })) };
}

