import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { verifyOutreachUnsubToken } from "@/lib/outreach/unsubscribe";
import { suppressEmail } from "@/lib/outreach/service";

export const dynamic = "force-dynamic";

const page = (title: string, body: string) =>
  new NextResponse(
    `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title}</title></head><body style="margin:0;background:#f4f4f8;font-family:Arial,Helvetica,sans-serif;"><div style="max-width:440px;margin:12vh auto;background:#fff;border-radius:12px;padding:32px;box-shadow:0 2px 12px rgba(0,0,0,.08);"><h1 style="margin:0 0 12px;font-size:20px;color:#1c1638;">${title}</h1>${body}</div></body></html>`,
    { headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store", "X-Robots-Tag": "noindex" } },
  );

/** GET shows a confirm button (link scanners that prefetch must not unsubscribe anyone). */
export async function GET(req: Request) {
  const t = new URL(req.url).searchParams.get("t") ?? "";
  const email = verifyOutreachUnsubToken(t);
  if (!email) return page("Link not valid", `<p style="color:#4a4763;font-size:15px;">This unsubscribe link is invalid or incomplete. Reply to the email with "UNSUBSCRIBE" and we'll remove you.</p>`);
  return page(
    "Unsubscribe",
    `<p style="color:#4a4763;font-size:15px;line-height:1.6;">Stop emails from Nxeon to <b>${email.replace(/</g, "&lt;")}</b>?</p><form method="post" action="/api/outreach/unsubscribe?t=${encodeURIComponent(t)}"><button style="background:#5b3df0;color:#fff;border:0;border-radius:8px;padding:12px 22px;font-size:15px;font-weight:bold;cursor:pointer;">Yes, unsubscribe me</button></form>`,
  );
}

/** POST performs it — also the RFC 8058 one-click target (List-Unsubscribe-Post). */
export async function POST(req: Request) {
  const t = new URL(req.url).searchParams.get("t") ?? "";
  const email = verifyOutreachUnsubToken(t);
  if (!email) return page("Link not valid", `<p style="color:#4a4763;">This unsubscribe link is invalid.</p>`);
  try {
    await suppressEmail(email, "UNSUBSCRIBE", "unsubscribe-link");
    const it = await db.outreachQueueItem.findFirst({ where: { email }, orderBy: { createdAt: "desc" }, select: { id: true, campaignId: true } });
    await db.outreachEvent.create({ data: { campaignId: it?.campaignId ?? null, itemId: it?.id ?? null, email, kind: "UNSUBSCRIBE", detail: "unsubscribe link" } });
  } catch (e) {
    console.error("[outreach-unsubscribe] failed", e);
    return page("Something went wrong", `<p style="color:#4a4763;">Please reply to the email with "UNSUBSCRIBE" instead.</p>`);
  }
  return page("You're unsubscribed", `<p style="color:#4a4763;font-size:15px;">We won't email you again.</p>`);
}
EOF
