/** Parse a sold game price back off Stripe metadata; null unless well-formed. */
export function parseGameOrderPrice(raw: unknown): GameOrderPrice | null {
  let obj: unknown = raw;
  if (typeof raw === "string") {
    try {
      obj = JSON.parse(raw);
    } catch {
      return null;
    }
  }
  if (!obj || typeof obj !== "object") return null;
  const { chargeCents, partnerDiscountCents, partnerDiscountTier } = obj as Record<string, unknown>;
  if (typeof chargeCents !== "number" || !Number.isInteger(chargeCents) || chargeCents < 0) return null;
  const out: GameOrderPrice = { chargeCents };
  if (typeof partnerDiscountCents === "number" && Number.isInteger(partnerDiscountCents) && partnerDiscountCents >= 0) {
    out.partnerDiscountCents = partnerDiscountCents;
  }
  if (partnerDiscountTier === "FIRST" || partnerDiscountTier === "RECURRING" || partnerDiscountTier === "NONE") {
    out.partnerDiscountTier = partnerDiscountTier;
  }
  return out;
}

