import test from "node:test";
import assert from "node:assert/strict";
import {
  renderOutreach, renderBody, buildVars, assembleEmail, assembleCodeEmail, findUnknownVars,
  SAMPLE_RECIPIENT, TEMPLATE_VARIABLES, fillText,
} from "../lib/outreach/render";
import { buildEmail, OUTREACH_V3_BODY, SUBJECT_TMPL } from "../lib/creator-outreach-template";
import { outreachUnsubToken, verifyOutreachUnsubToken } from "../lib/outreach/unsubscribe";

process.env.AUTH_SECRET = "test-secret";
const footer = { brandName: "Nxeon", postalAddress: "1 Test St, Toronto ON", unsubscribeUrl: "https://nxeon.cloud/api/outreach/unsubscribe?t=abc" };
const sig = { signatureHtml: "<b>Santino</b>", signatureText: "Santino" };
const ctx = { claimUrl: "https://nxeon.cloud/partner/claim?token=PREVIEW", unsubscribeUrl: footer.unsubscribeUrl, senderName: "Santino Rossi" };

test("renderer is deterministic", () => {
  const vars = buildVars(SAMPLE_RECIPIENT, ctx);
  const a = renderOutreach({ subject: SUBJECT_TMPL, body: OUTREACH_V3_BODY, vars, ...sig, footer });
  const b = renderOutreach({ subject: SUBJECT_TMPL, body: OUTREACH_V3_BODY, vars, ...sig, footer });
  assert.equal(a.html, b.html);
  assert.equal(a.text, b.text);
  assert.equal(a.subject, "Alex Morgan × Nxeon — Sponsorship Offer");
});

test("built-in template body renders the same HTML as the legacy buildEmail()", () => {
  const vars = buildVars({ email: "x@y.co", fullName: "Dana Lee", game: "Rust" }, ctx);
  const legacy = buildEmail({ fullName: "Dana Lee", firstName: "Dana", game: "Rust" }, ctx.claimUrl);
  const body = renderBody(OUTREACH_V3_BODY, vars);
  assert.equal(body.html, legacy.html);
  assert.equal(fillText(SUBJECT_TMPL, vars), legacy.subject);
});

test("preview == send: footer, signature and claim link are always present", () => {
  const vars = buildVars(SAMPLE_RECIPIENT, ctx);
  const r = renderOutreach({ subject: "Hi {{firstName}}", body: "Hello {{firstName}}\n\n[[button: Claim | {{claimUrl}}]]", vars, ...sig, footer });
  assert.match(r.html, /<b>Santino<\/b>/);
  assert.ok(r.html.includes(ctx.claimUrl));
  assert.ok(r.html.includes("1 Test St, Toronto ON"));
  assert.ok(r.html.includes(footer.unsubscribeUrl));
  assert.ok(r.text.includes(ctx.claimUrl));
  assert.ok(r.text.includes("UNSUBSCRIBE"));
});

test("CAN-SPAM: a missing postal address or unsubscribe link is refused for every kind", () => {
  const base = { subject: "s", bodyHtml: "<p>x</p>", bodyText: "x", ...sig };
  assert.throws(() => assembleEmail({ ...base, footer: { ...footer, postalAddress: " " } }), /postal address/);
  assert.throws(() => assembleEmail({ ...base, footer: { ...footer, unsubscribeUrl: "" } }), /unsubscribe/);
  assert.throws(() => assembleCodeEmail({ subject: "s", html: "<body></body>", text: "x", footer: { ...footer, postalAddress: "" } }), /postal address/);
  const ok = assembleCodeEmail({ subject: "s", html: "<html><body><p>x</p></body></html>", text: "x", footer });
  assert.ok(ok.html.indexOf("1 Test St") < ok.html.indexOf("</body>"));
});

test("variable values are escaped and can never inject markup or links", () => {
  const vars = buildVars({ email: "a@b.co", fullName: '<img src=x onerror=1> **b** [x](javascript:alert(1))', game: "G" }, ctx);
  const { html } = renderBody("Hi {{fullName}}", vars);
  assert.ok(!html.includes("<img"));
  assert.ok(!/<strong>b<\/strong>/.test(html) || html.includes("&lt;img"));
  assert.ok(!html.includes("javascript:"), "no javascript: href survives");
});

test("template links: only http(s)/mailto are linked", () => {
  const vars = buildVars(SAMPLE_RECIPIENT, ctx);
  const { html } = renderBody("[ok](https://a.example/x) and [bad](javascript:alert(1))", vars);
  assert.match(html, /<a href="https:\/\/a\.example\/x"/);
  assert.ok(!html.includes('href="javascript'));
});

test("unknown variables are reported; defaults fill blanks", () => {
  assert.deepEqual(findUnknownVars("Hi {{firstName}} {{nope}} {{ alsoNope }}"), ["nope", "alsoNope"]);
  for (const v of TEMPLATE_VARIABLES) assert.deepEqual(findUnknownVars(`{{${v}}}`), []);
  const v = buildVars({ email: "a@b.co" }, ctx);
  assert.equal(v.firstName, "there");
  assert.equal(v.game, "your game");
});

test("unsubscribe tokens round-trip and reject tampering", () => {
  const t = outreachUnsubToken("Dana@Example.com");
  assert.equal(verifyOutreachUnsubToken(t), "dana@example.com");
  assert.equal(verifyOutreachUnsubToken(t.slice(0, -2) + "xx"), null);
  assert.equal(verifyOutreachUnsubToken("garbage"), null);
});
