import test from "node:test";
import assert from "node:assert/strict";
import { readGrid, suggestMapping, applyMapping, classifyRows, summarize, validEmail } from "../lib/outreach/csv";

const csv = `Name,Youtube Channel,Primary game,Email,Country,Subscriber count,Emailed
Dana Lee,https://youtube.com/@dana,Rust,Dana@Example.com,Canada,"12,000",
Bob,,Valheim,bob@example.com,,,
Dup,,Rust,dana@example.com,,,
Bad,,Rust,not-an-email,,,
"Quote, Inc",,Palworld,q@example.com,,,
Sup,,Rust,gone@example.com,,,
Inv,,Rust,invited@example.com,,,
Par,,Rust,partner@example.com,,,
Que,,Rust,queued@example.com,,,`;

test("header mapping is suggested and rows parsed (quotes, case, BOM-free)", () => {
  const g = readGrid(csv);
  const m = suggestMapping(g.headers);
  assert.equal(m.email, 3);
  assert.equal(m.name, 0);
  assert.equal(m.game, 2);
  assert.equal(m.channel, 1);
  assert.equal(m.subscribers, 5);
  const rows = applyMapping(g.rows, m);
  assert.equal(rows.length, 9);
  assert.equal(rows[0].email, "dana@example.com");
  assert.equal(rows[0].subscribers, "12,000");
  assert.equal(rows[4].name, "Quote, Inc");
  assert.equal(rows[0].line, 2);
});

test("custom headers can be re-mapped by the admin", () => {
  const g = readGrid("Who,Mail,Title\nA,a@b.co,Rust");
  const m = suggestMapping(g.headers);
  assert.equal(m.email, 1); // 'mail' synonym
  const rows = applyMapping(g.rows, { email: 1, name: 0, game: 2 });
  assert.deepEqual([rows[0].name, rows[0].email, rows[0].game], ["A", "a@b.co", "Rust"]);
});

test("validation + dedupe verdicts", () => {
  const rows = applyMapping(readGrid(csv).rows, suggestMapping(readGrid(csv).headers));
  const out = classifyRows(rows, {
    queued: new Set(["queued@example.com"]), invited: new Set(["invited@example.com"]),
    partners: new Set(["partner@example.com"]), suppressed: new Set(["gone@example.com"]),
  });
  const v = (e: string) => out.find((x) => x.row.email === e)!.verdict;
  assert.equal(v("dana@example.com"), "ok"); // first occurrence wins
  assert.equal(out[2].verdict, "duplicate-in-file");
  assert.equal(v("not-an-email"), "invalid-email");
  assert.equal(v("gone@example.com"), "suppressed");
  assert.equal(v("invited@example.com"), "already-invited");
  assert.equal(v("partner@example.com"), "already-partner");
  assert.equal(v("queued@example.com"), "already-queued");
  const s = summarize(out);
  assert.equal(s.ok, 3); // dana, bob, q@
  assert.equal(s["duplicate-in-file"], 1);
});

test("email validation", () => {
  assert.ok(validEmail("a.b+c@sub.example.co"));
  for (const bad of ["", "a@b", "a b@c.de", "a@@b.co", "<a@b.co>", "a@b.c"]) assert.ok(!validEmail(bad), bad);
});

test("empty / missing-email CSV", () => {
  assert.ok(readGrid("").error);
  assert.deepEqual(applyMapping(readGrid("A,B\n,,\n").rows, { email: 0 }), []);
});
