cat > test/outreach-inbound.test.ts <<'EOF'
import test from "node:test";
import assert from "node:assert/strict";
import { classifyInbound, type InboundMessage } from "../lib/outreach/inbound";
import { grantPhase } from "../lib/partner-grants";

const rec = new Set(["dana@example.com", "bob@example.com"]);
const m = (o: Partial<InboundMessage>): InboundMessage => ({ uid: 1, messageId: "<1@x>", inReplyTo: null, fromAddress: "x@y.z", subject: "", date: new Date(), text: "", ...o });

test("human reply from a recipient", () => {
  const r = classifyInbound(m({ fromAddress: "Dana@Example.com", subject: "Re: Dana × Nxeon — Sponsorship Offer", text: "Sounds good, tell me more" }), rec)!;
  assert.equal(r.kind, "REPLY");
  assert.equal(r.email, "dana@example.com");
});

test("bounce DSN is matched to the failed recipient", () => {
  const r = classifyInbound(m({ fromAddress: "MAILER-DAEMON@mail.nxeon.cloud", fromName: "Mail Delivery System", subject: "Undelivered Mail Returned to Sender", text: "Final-Recipient: rfc822; bob@example.com\nAction: failed\nStatus: 5.1.1" }), rec)!;
  assert.equal(r.kind, "BOUNCE");
  assert.equal(r.email, "bob@example.com");
});

test("bounce for an address we never emailed is ignored", () => {
  assert.equal(classifyInbound(m({ fromAddress: "mailer-daemon@x.com", subject: "Delivery Status Notification (Failure)", text: "to stranger@else.com" }), rec), null);
});

test("unsubscribe request wins over reply; auto-replies and strangers ignored", () => {
  assert.equal(classifyInbound(m({ fromAddress: "bob@example.com", subject: "Re: hi", text: "Please unsubscribe me" }), rec)!.kind, "UNSUBSCRIBE");
  assert.equal(classifyInbound(m({ fromAddress: "bob@example.com", subject: "Automatic reply: out of office", text: "unsubscribe" }), rec), null);
  assert.equal(classifyInbound(m({ fromAddress: "random@else.com", subject: "Re: hi", text: "hello" }), rec), null);
});

test("grant lifecycle phases", () => {
  const exp = new Date("2026-11-01T00:00:00Z");
  const g = { expiresAt: exp, noticeSentAt: null as Date | null, finalNoticeSentAt: null as Date | null };
  const d = (days: number) => new Date(exp.getTime() - days * 86_400_000);
  assert.equal(grantPhase(g, exp, d(20)), "none");
  assert.equal(grantPhase(g, exp, d(6)), "notice");
  assert.equal(grantPhase({ ...g, noticeSentAt: d(6) }, exp, d(5)), "none");
  assert.equal(grantPhase({ ...g, noticeSentAt: d(6) }, exp, d(0.5)), "final");
  assert.equal(grantPhase({ ...g, noticeSentAt: d(6), finalNoticeSentAt: d(0.5) }, exp, d(0.2)), "none");
  assert.equal(grantPhase(g, exp, new Date(exp.getTime() + 1000)), "expired");
  // renewed by the partner: server term moved well past the grant
  assert.equal(grantPhase(g, new Date(exp.getTime() + 30 * 86_400_000), d(1)), "converted");
});
