import test from "node:test";
import assert from "node:assert/strict";
import {
  nextDelaySeconds, windowIsOpen, nextWindowOpen, effectiveDailyCap, canSendNow, localDayKey, daysSince,
  parseDays, type PacingConfig,
} from "../lib/outreach/pacing";
import { nextStatus, allowedActions, itemActionAllowed, canEditRecipients } from "../lib/outreach/state";

const base: PacingConfig = {
  intervalSeconds: 60, jitterPct: 0, windowStartHour: 9, windowEndHour: 17, timezone: "America/Toronto",
  days: "1,2,3,4,5", dailyCap: null, warmupEnabled: false, warmupStartCap: 10, warmupStep: 10,
};
// 2026-10-05 is a Monday. Toronto is UTC-4 in October (EDT).
const mon = (h: number, m = 0) => new Date(Date.UTC(2026, 9, 5, h + 4, m));

test("delay: no jitter is exact; jitter stays in range; floor enforced", () => {
  assert.equal(nextDelaySeconds(60, 0, () => 0.9), 60);
  assert.equal(nextDelaySeconds(100, 50, () => 0), 50);
  assert.equal(nextDelaySeconds(100, 50, () => 1), 150);
  assert.equal(nextDelaySeconds(100, 50, () => 0.5), 100);
  assert.ok(nextDelaySeconds(1, 100, () => 0) >= 5);
});

test("window: hours, weekdays and timezone", () => {
  assert.equal(windowIsOpen(mon(8, 59), base), false);
  assert.equal(windowIsOpen(mon(9, 0), base), true);
  assert.equal(windowIsOpen(mon(16, 59), base), true);
  assert.equal(windowIsOpen(mon(17, 0), base), false);
  const sat = new Date(Date.UTC(2026, 9, 10, 15)); // Saturday 11:00 Toronto
  assert.equal(windowIsOpen(sat, base), false);
  assert.equal(windowIsOpen(sat, { ...base, days: "1,2,3,4,5,6,7" }), true);
  assert.equal(windowIsOpen(mon(3), { ...base, windowStartHour: null, windowEndHour: null }), true);
});

test("window wrapping midnight", () => {
  const w = { ...base, windowStartHour: 22, windowEndHour: 6, days: "1,2,3,4,5,6,7" };
  assert.equal(windowIsOpen(mon(23), w), true);
  assert.equal(windowIsOpen(mon(5), w), true);
  assert.equal(windowIsOpen(mon(12), w), false);
});

test("nextWindowOpen finds Monday 9:00 from Friday evening", () => {
  const fri = new Date(Date.UTC(2026, 9, 9, 22)); // Fri 18:00 Toronto
  const n = nextWindowOpen(fri, base)!;
  assert.equal(localDayKey(n, base.timezone), "2026-10-12");
  assert.ok(n.getTime() - Date.UTC(2026, 9, 12, 13) < 6 * 60_000); // 09:00 EDT = 13:00Z (within the 5-min scan step)
});

test("warm-up ramp and daily cap combine", () => {
  const start = mon(10);
  const c = { ...base, warmupEnabled: true, warmupStartCap: 10, warmupStep: 5, dailyCap: 40 };
  assert.equal(effectiveDailyCap(c, start, mon(11)), 10);
  assert.equal(effectiveDailyCap(c, start, new Date(start.getTime() + 2 * 86_400_000)), 20);
  assert.equal(effectiveDailyCap(c, start, new Date(start.getTime() + 20 * 86_400_000)), 40);
  assert.equal(effectiveDailyCap({ ...base, dailyCap: null }, start, mon(11)), null);
  assert.equal(daysSince(start, new Date(start.getTime() + 3 * 86_400_000), base.timezone), 3);
});

test("canSendNow: not-yet, window-closed, daily-cap, ok", () => {
  const s = { nextSendAt: null as Date | null, startedAt: mon(9), sentToday: 0 };
  assert.deepEqual(canSendNow(base, s, mon(10)), { ok: true });
  const soon = new Date(mon(10).getTime() + 30_000);
  const a = canSendNow(base, { ...s, nextSendAt: soon }, mon(10));
  assert.equal(a.ok === false && a.reason, "not-yet");
  const b = canSendNow(base, s, mon(18));
  assert.equal(b.ok === false && b.reason, "window-closed");
  const c = canSendNow({ ...base, dailyCap: 5 }, { ...s, sentToday: 5 }, mon(10));
  assert.ok(c.ok === false && c.reason === "daily-cap" && c.retryAt && localDayKey(c.retryAt, base.timezone) === "2026-10-06");
  assert.equal(canSendNow({ ...base, dailyCap: 5 }, { ...s, sentToday: 4 }, mon(10)).ok, true);
});

test("days parsing", () => {
  assert.deepEqual(parseDays("5, 1,1,9,x,7"), [1, 5, 7]);
});

test("campaign state machine", () => {
  assert.equal(nextStatus("DRAFT", "start"), "RUNNING");
  assert.equal(nextStatus("RUNNING", "pause"), "PAUSED");
  assert.equal(nextStatus("PAUSED", "resume"), "RUNNING");
  assert.equal(nextStatus("RUNNING", "complete"), "COMPLETED");
  assert.equal(nextStatus("PAUSED", "stop"), "CANCELLED");
  assert.equal(nextStatus("COMPLETED", "start"), null);
  assert.equal(nextStatus("CANCELLED", "resume"), null);
  assert.equal(nextStatus("DRAFT", "pause"), null);
  assert.equal(nextStatus("COMPLETED", "reopen"), "PAUSED"); // never straight back to RUNNING
  assert.deepEqual(allowedActions("DRAFT").sort(), ["start", "stop"]);
  assert.equal(canEditRecipients("COMPLETED"), false);
  assert.equal(canEditRecipients("PAUSED"), true);
});

test("recipient actions respect status", () => {
  assert.equal(itemActionAllowed("SENT", "retry"), false);
  assert.equal(itemActionAllowed("FAILED", "retry"), true);
  assert.equal(itemActionAllowed("SENDING", "skip"), false);
  assert.equal(itemActionAllowed("SENDING", "remove"), false);
  assert.equal(itemActionAllowed("SENT", "edit"), false);
  assert.equal(itemActionAllowed("QUEUED", "send-now"), true);
});
