} from "@/lib/actions-partner-invite";

/* Admin: Creator Partner invites. Creating NEVER emails anyone — invites are
 * DRAFTS until the admin presses Send (per invite) or "Send all drafts", each
 * behind a confirm that lists the count and the recipients. A claim link is
 * shown ONCE after a send (only its hash is stored), so an invite can also be
 * delivered by DM — and staging, which has no SMTP, can still be tested. */

function CopyLink({ link }: { link: string }) {
  const [done, setDone] = useState(false);
  return (
    <span className="flex min-w-0 items-center gap-2">
      <input readOnly value={link} onFocus={(e) => e.currentTarget.select()} className="input h-8 min-w-0 flex-1 font-mono text-xs" />
      <button
        type="button"
        className="btn-secondary h-8 px-2.5 text-xs"
        onClick={async () => {
          try { await navigator.clipboard.writeText(link); setDone(true); setTimeout(() => setDone(false), 1500); } catch { /* select + copy manually */ }
        }}
      >
        {done ? "Copied" : "Copy"}
      </button>
    </span>
  );
}

function SendResults({ results }: { results: SendResult[] }) {
  return (
    <ul className="space-y-2 rounded-lg border border-slate-800 p-3 text-left text-sm">
      {results.map((r) => (
        <li key={r.id} className="space-y-1">
          <div>
            <span className="font-mono text-slate-200">{r.email}</span>{" "}
            {!r.ok ? (
              <span className="text-red-400">— {r.error}</span>
            ) : r.sent ? (
              <span className="text-emerald-400">— emailed</span>
            ) : (
              <span className="text-amber-300">— marked sent, but the email was NOT delivered (mail not configured?). Send this link yourself:</span>
