"use client";

import { useState, useTransition } from "react";
import { analyzeOutreachCsv, importOutreachCsv, previewOutreachImport } from "@/lib/actions-outreach";

const FIELD_LABELS: [string, string][] = [
  ["email", "Email *"], ["name", "Name"], ["game", "Primary game"], ["channel", "Channel URL"], ["country", "Country"], ["subscribers", "Subscribers"],
];
const VERDICT_TEXT: Record<string, string> = {
  ok: "will be added", "invalid-email": "invalid email", "duplicate-in-file": "duplicate in this file", "already-queued": "already in a campaign queue",
  "already-invited": "already invited", "already-partner": "already a partner", suppressed: "on the suppression list",
};

/** Upload CSV -> map columns -> validate + dedupe preview -> import. Nothing is queued until "Add to campaign". */
export function CsvImport({ campaignId }: { campaignId: string }) {
  const [csv, setCsv] = useState("");
  const [info, setInfo] = useState<{ headers: string[]; sample: string[][]; total: number } | null>(null);
  const [map, setMap] = useState<Record<string, number>>({});
  const [prev, setPrev] = useState<Awaited<ReturnType<typeof previewOutreachImport>> | null>(null);
  const [msg, setMsg] = useState<string | null>(null);
  const [pending, start] = useTransition();

  function onFile(e: React.ChangeEvent<HTMLInputElement>) {
    const f = e.target.files?.[0];
    e.target.value = "";
    if (!f) return;
    const r = new FileReader();
    r.onload = () => {
      const text = String(r.result ?? "");
      setCsv(text); setPrev(null); setMsg(null);
      start(async () => {
        const a = await analyzeOutreachCsv(text);
        if ("error" in a && a.error) { setInfo(null); setMsg(a.error); return; }
        const ok = a as { headers: string[]; mapping: Record<string, number>; sample: string[][]; total: number };
        setInfo({ headers: ok.headers, sample: ok.sample, total: ok.total });
        setMap(ok.mapping);
        const p = await previewOutreachImport(text, ok.mapping);
        setPrev(p);
      });
    };
    r.readAsText(f);
  }
  function recheck(next: Record<string, number>) {
    setMap(next); setMsg(null);
    start(async () => setPrev(await previewOutreachImport(csv, next)));
  }

  return (
    <div className="space-y-3 text-sm">
      <label className="inline-flex cursor-pointer items-center rounded-lg border border-white/10 bg-white/5 px-3 py-1.5 hover:bg-white/10">
        <input type="file" accept=".csv,text/csv" className="hidden" onChange={onFile} disabled={pending} />
        {pending ? "Working…" : info ? "Choose a different CSV" : "Upload recipient CSV"}
      </label>
      {msg && <p className="text-slate-300">{msg}</p>}
      {info && (
        <>
          <p className="text-xs text-slate-500">{info.total} data rows. Match each field to a column (guessed from the headers):</p>
          <div className="grid grid-cols-2 gap-3 sm:grid-cols-3">
            {FIELD_LABELS.map(([k, label]) => (
              <label key={k} className="block">
                <span className="label">{label}</span>
                <select className="input h-9 w-full" value={map[k] ?? -1} onChange={(e) => recheck({ ...map, [k]: Number(e.target.value) })}>
                  <option value={-1}>— not in the file —</option>
                  {info.headers.map((h, i) => <option key={i} value={i}>{h || `(column ${i + 1})`}</option>)}
                </select>
              </label>
            ))}
          </div>
        </>
      )}
      {prev && "error" in prev && prev.error && <p className="text-red-400">{prev.error}</p>}
      {prev && "counts" in prev && prev.counts && (
        <div className="space-y-2 rounded-lg border border-white/10 p-3">
          <p className="text-slate-200">
            <b className="text-emerald-400">{prev.counts.ok}</b> will be added of {prev.total}.
            {Object.entries(prev.counts).filter(([k, n]) => k !== "ok" && n > 0).map(([k, n]) => <span key={k} className="ml-3 text-amber-300">{n} {VERDICT_TEXT[k]}</span>)}
          </p>
          {prev.problems.length > 0 && (
            <details className="text-xs text-slate-400">
              <summary className="cursor-pointer">Rows that will be skipped</summary>
              <ul className="mt-1 max-h-40 overflow-auto font-mono">
                {prev.problems.map((p) => <li key={p.line}>line {p.line}: {p.email || "(blank)"} — {VERDICT_TEXT[p.verdict]}</li>)}
              </ul>
            </details>
          )}
          <button
            type="button" className="btn-primary h-9 px-4" disabled={pending || prev.counts.ok === 0}
            onClick={() => start(async () => {
              const r = await importOutreachCsv(campaignId, csv, map);
              if ("error" in r && r.error) setMsg(r.error);
              else { setMsg(`Added ${r.added} recipient${r.added === 1 ? "" : "s"}.`); setInfo(null); setPrev(null); setCsv(""); }
            })}
          >
            Add {prev.counts.ok} to campaign
          </button>
        </div>
      )}
    </div>
  );
}
EOF

