                      </>
                    )}
                    {canEdit && (r.status === "QUEUED" || r.status === "FAILED" || r.status === "SKIPPED") && <button className="text-slate-300 hover:underline" disabled={pending} onClick={() => setEdit(r)}>Edit</button>}
                    {canEdit && (r.status === "QUEUED" || r.status === "FAILED") && <button className="text-brand-300 hover:underline" disabled={pending} onClick={() => { if (confirm(`Send to ${r.email} right now?`)) run(() => outreachSendNow(r.id)); }}>Send now</button>}
                    {canEdit && r.status === "FAILED" && <button className="text-amber-300 hover:underline" disabled={pending} onClick={() => run(() => outreachItemAction(r.id, "retry"))}>Retry</button>}
                    {canEdit && (r.status === "QUEUED" || r.status === "FAILED") && <button className="text-slate-400 hover:underline" disabled={pending} onClick={() => run(() => outreachItemAction(r.id, "skip"))}>Skip</button>}
                    {canEdit && r.status === "SKIPPED" && <button className="text-slate-300 hover:underline" disabled={pending} onClick={() => run(() => outreachItemAction(r.id, "unskip"))}>Un-skip</button>}
                    {canEdit && r.status !== "SENT" && r.status !== "SENDING" && <button className="text-red-400 hover:underline" disabled={pending} onClick={() => { if (confirm(`Remove ${r.email} from this campaign?`)) run(() => outreachItemAction(r.id, "remove")); }}>Remove</button>}
                  </span>
