          <div className="w-full max-w-md rounded-2xl border border-white/10 bg-navy-900 p-4 text-sm" onClick={(e) => e.stopPropagation()}>
            <p className="mb-2 font-semibold text-white">Timeline — <span className="font-mono text-xs">{timeline.email}</span></p>
            {timeline.rows.length === 0 ? <p className="text-slate-500">Nothing yet.</p> : (
              <ul className="max-h-80 space-y-1 overflow-auto">
                {timeline.rows.map((t, i) => <li key={i} className="flex gap-3 text-xs"><span className="w-32 shrink-0 text-slate-500">{t.at.slice(0, 16).replace("T", " ")}</span><span className="w-24 shrink-0 text-slate-200">{t.kind.toLowerCase()}</span><span className="truncate text-slate-400">{t.detail}</span></li>)}
              </ul>
