"use client";

import { useRouter } from "next/navigation";
import { useState, useTransition } from "react";
import {
  controlOutreachCampaign, createOutreachCampaign, deleteOutreachCampaign, outreachSendNextNow,
  previewOutreachTemplate, sendOutreachTestEmail, setOutreachKillSwitch, updateOutreachCampaign,
} from "@/lib/actions-outreach";
import { PreviewModal, type PreviewData } from "./PreviewModal";

export type TemplateOpt = { id: string; name: string; kind: string; archived: boolean };
export type CampaignSettings = {
  id?: string; name: string; templateId: string; senderAddress: string; subjectOverride: string; bodyOverride: string;
  intervalSeconds: number; jitterPct: number; windowStartHour: number | null; windowEndHour: number | null;
  timezone: string; days: string; dailyCap: number | null; warmupEnabled: boolean; warmupStartCap: number; warmupStep: number;
};
const DAYS = [["1", "Mon"], ["2", "Tue"], ["3", "Wed"], ["4", "Thu"], ["5", "Fri"], ["6", "Sat"], ["7", "Sun"]];
const num = (v: string) => (v.trim() === "" ? null : Number(v));

export function KillSwitch({ on }: { on: boolean }) {
  const router = useRouter();
  const [pending, start] = useTransition();
  return (
    <div className={`flex flex-wrap items-center justify-between gap-3 rounded-xl border px-4 py-3 text-sm ${on ? "border-red-500/40 bg-red-500/10" : "border-white/10 bg-white/[0.02]"}`}>
      <div>
        <p className="font-semibold text-white">Global outreach kill switch: {on ? <span className="text-red-400">ON — nothing sends</span> : <span className="text-emerald-400">off</span>}</p>
        <p className="text-xs text-slate-400">Stops every campaign&apos;s worker sends instantly (and manual &quot;send now&quot;). Campaign states are untouched; turn it off to carry on.</p>
      </div>
      <button
        type="button" disabled={pending} className={on ? "btn-primary h-9 px-4" : "h-9 rounded-lg border border-red-500/40 bg-red-500/10 px-4 text-red-300 hover:bg-red-500/20"}
        onClick={() => { if (!on && !confirm("Stop ALL outreach sending right now?")) return; start(async () => { await setOutreachKillSwitch(!on); router.refresh(); }); }}
      >
        {on ? "Resume sending" : "Stop everything"}
      </button>
    </div>
  );
}

export function SettingsFields({ s, set, templates, mailboxes }: { s: CampaignSettings; set: (p: Partial<CampaignSettings>) => void; templates: TemplateOpt[]; mailboxes: string[] }) {
  const days = new Set(s.days.split(","));
  const perHour = s.intervalSeconds > 0 ? Math.round((3600 / s.intervalSeconds) * 10) / 10 : 0;
  return (
    <div className="space-y-4 text-sm">
      <div className="grid gap-3 sm:grid-cols-2">
        <label className="block"><span className="label">Campaign name</span><input className="input w-full" value={s.name} maxLength={120} onChange={(e) => set({ name: e.target.value })} /></label>
        <label className="block"><span className="label">Template</span>
          <select className="input w-full" value={s.templateId} onChange={(e) => set({ templateId: e.target.value })}>
            {templates.filter((t) => !t.archived || t.id === s.templateId).map((t) => <option key={t.id} value={t.id}>{t.name}{t.kind === "CODE" ? " (code)" : ""}{t.archived ? " [archived]" : ""}</option>)}
          </select>
        </label>
        <label className="block"><span className="label">Send as (sender mailbox)</span>
          <select className="input w-full" value={s.senderAddress} onChange={(e) => set({ senderAddress: e.target.value })}>
            {mailboxes.map((m) => <option key={m} value={m}>{m}</option>)}
          </select>
        </label>
      </div>
      <div className="rounded-lg border border-white/10 p-3">
        <p className="section-label">Pacing</p>
        <div className="mt-2 grid gap-3 sm:grid-cols-4">
          <label className="block"><span className="label">Seconds between emails</span><input type="number" min={5} className="input w-full" value={s.intervalSeconds} onChange={(e) => set({ intervalSeconds: Number(e.target.value) })} /></label>
          <label className="block"><span className="label">Random jitter ± %</span><input type="number" min={0} max={100} className="input w-full" value={s.jitterPct} onChange={(e) => set({ jitterPct: Number(e.target.value) })} /></label>
          <label className="block"><span className="label">Daily cap (blank = none)</span><input type="number" min={1} className="input w-full" value={s.dailyCap ?? ""} onChange={(e) => set({ dailyCap: num(e.target.value) })} /></label>
          <p className="self-end pb-2 text-xs text-slate-500">≈ {perHour}/hour at the base interval</p>
        </div>
        <div className="mt-3 grid gap-3 sm:grid-cols-4">
          <label className="block"><span className="label">Window opens (hour)</span><input type="number" min={0} max={24} className="input w-full" placeholder="always" value={s.windowStartHour ?? ""} onChange={(e) => set({ windowStartHour: num(e.target.value) })} /></label>
          <label className="block"><span className="label">Window closes (hour)</span><input type="number" min={0} max={24} className="input w-full" placeholder="always" value={s.windowEndHour ?? ""} onChange={(e) => set({ windowEndHour: num(e.target.value) })} /></label>
          <label className="block sm:col-span-2"><span className="label">Timezone (IANA)</span><input className="input w-full font-mono" value={s.timezone} onChange={(e) => set({ timezone: e.target.value })} /></label>
        </div>
        <div className="mt-3 flex flex-wrap items-center gap-3">
          <span className="label m-0">Days</span>
          {DAYS.map(([d, l]) => (
            <label key={d} className="inline-flex items-center gap-1.5 text-slate-300">
              <input type="checkbox" checked={days.has(d)} onChange={(e) => { const n = new Set(days); if (e.target.checked) n.add(d); else n.delete(d); set({ days: [...n].sort().join(",") }); }} /> {l}
            </label>
          ))}
        </div>
        <div className="mt-3 flex flex-wrap items-center gap-4">
          <label className="inline-flex items-center gap-2 text-slate-300"><input type="checkbox" checked={s.warmupEnabled} onChange={(e) => set({ warmupEnabled: e.target.checked })} /> Warm-up ramp</label>
          {s.warmupEnabled && (
            <>
              <label className="inline-flex items-center gap-2 text-slate-300">start at <input type="number" min={1} className="input h-8 w-20" value={s.warmupStartCap} onChange={(e) => set({ warmupStartCap: Number(e.target.value) })} /> /day</label>
              <label className="inline-flex items-center gap-2 text-slate-300">+ <input type="number" min={0} className="input h-8 w-20" value={s.warmupStep} onChange={(e) => set({ warmupStep: Number(e.target.value) })} /> each day (never above the daily cap)</label>
            </>
          )}
        </div>
      </div>
      <details className="rounded-lg border border-white/10 p-3">
        <summary className="cursor-pointer text-slate-300">Per-campaign copy override (optional — leaves the template itself untouched)</summary>
        <div className="mt-3 space-y-3">
          <label className="block"><span className="label">Subject override</span><input className="input w-full" value={s.subjectOverride} onChange={(e) => set({ subjectOverride: e.target.value })} placeholder="blank = template subject" /></label>
          <label className="block"><span className="label">Body override</span><textarea rows={8} className="input w-full font-mono text-xs" value={s.bodyOverride} onChange={(e) => set({ bodyOverride: e.target.value })} placeholder="blank = template body (same syntax as the template editor)" /></label>
        </div>
      </details>
    </div>
  );
}

export const DEFAULT_SETTINGS: CampaignSettings = {
  name: "", templateId: "", senderAddress: "santino@nxeon.cloud", subjectOverride: "", bodyOverride: "", intervalSeconds: 90, jitterPct: 30,
  windowStartHour: 9, windowEndHour: 17, timezone: "America/Toronto", days: "1,2,3,4,5", dailyCap: 40, warmupEnabled: false, warmupStartCap: 10, warmupStep: 10,
};

export function NewCampaignForm({ templates, mailboxes }: { templates: TemplateOpt[]; mailboxes: string[] }) {
  const router = useRouter();
  const [s, setS] = useState<CampaignSettings>({ ...DEFAULT_SETTINGS, templateId: templates.find((t) => !t.archived)?.id ?? "", senderAddress: mailboxes.includes("santino@nxeon.cloud") ? "santino@nxeon.cloud" : mailboxes[0] ?? "" });
  const [err, setErr] = useState<string | null>(null);
  const [pending, start] = useTransition();
  return (
    <div className="space-y-3">
      <SettingsFields s={s} set={(p) => setS((x) => ({ ...x, ...p }))} templates={templates} mailboxes={mailboxes} />
      {err && <p className="text-sm text-red-400">{err}</p>}
      <button
        type="button" className="btn-primary h-9 px-4" disabled={pending}
        onClick={() => start(async () => {
          const r = await createOutreachCampaign({ ...s, subjectOverride: s.subjectOverride || null, bodyOverride: s.bodyOverride || null });
          if (r.error) setErr(r.error); else if (r.id) router.push(`/admin/partners/outreach/${r.id}`);
        })}
      >
        Create draft campaign
      </button>
      <p className="text-xs text-slate-500">A new campaign is a draft: add recipients, preview, then Start. Nothing sends until you press Start.</p>
    </div>
  );
}

export function CampaignControls({ id, status, settings, templates, mailboxes, hasQueued, pauseReason, isLegacy }: {
  id: string; status: string; settings: CampaignSettings; templates: TemplateOpt[]; mailboxes: string[]; hasQueued: boolean; pauseReason: string | null; isLegacy: boolean;
}) {
  const router = useRouter();
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<string | null>(null);
  const [s, setS] = useState(settings);
  const [editing, setEditing] = useState(false);
  const [preview, setPreview] = useState<PreviewData | null>(null);
  const [testTo, setTestTo] = useState("");
  const act = (a: "start" | "pause" | "resume" | "stop" | "reopen", confirmText?: string) => {
    if (confirmText && !confirm(confirmText)) return;
    start(async () => { const r = await controlOutreachCampaign(id, a); setMsg(r.error ?? null); router.refresh(); });
  };
  const closed = status === "COMPLETED" || status === "CANCELLED";
  return (
    <div className="space-y-4">
      {pauseReason && <div className="rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-sm text-amber-200">Paused automatically: {pauseReason}. Check the failed rows, then Resume.</div>}
      <div className="flex flex-wrap items-center gap-2">
        {status === "DRAFT" && <button className="btn-primary h-9 px-4" disabled={pending || !hasQueued} onClick={() => act("start", "Start sending? Emails go out at the pacing below, to every queued recipient.")}>Start</button>}
        {status === "RUNNING" && <button className="btn-secondary h-9 px-4" disabled={pending} onClick={() => act("pause")}>Pause</button>}
        {status === "PAUSED" && <button className="btn-primary h-9 px-4" disabled={pending} onClick={() => act("resume")}>Resume</button>}
        {(status === "RUNNING" || status === "PAUSED") && hasQueued && (
          <button className="btn-secondary h-9 px-4" disabled={pending} onClick={() => { if (!confirm("Send the next queued recipient right now (ignores pacing, window and cap)?")) return; start(async () => { const r = await outreachSendNextNow(id); setMsg(r.error ?? "Sent."); router.refresh(); }); }}>Send next now</button>
        )}
        {!closed && <button className="h-9 rounded-lg border border-red-500/40 px-4 text-red-300 hover:bg-red-500/10" disabled={pending} onClick={() => act("stop", "Stop (cancel) this campaign? Unsent recipients stay queued but nothing will send until you reopen it.")}>Stop</button>}
        {closed && <button className="btn-secondary h-9 px-4" disabled={pending} onClick={() => act("reopen")}>Reopen (paused)</button>}
        {!closed && <button className="btn-secondary h-9 px-4" onClick={() => setEditing((e) => !e)}>{editing ? "Hide settings" : "Settings"}</button>}
        <button
          className="btn-secondary h-9 px-4" disabled={pending}
          onClick={() => start(async () => { const r = await previewOutreachTemplate({ campaignId: id }); if ("error" in r && r.error) setMsg(r.error); else setPreview(r as PreviewData); })}
        >Preview campaign email</button>
        {!isLegacy && status !== "RUNNING" && (
          <button className="ml-auto h-9 rounded-lg px-3 text-xs text-slate-500 hover:text-red-400" disabled={pending}
            onClick={() => { if (!confirm("Delete this campaign and its recipient list? Send history stays in the email log.")) return; start(async () => { const r = await deleteOutreachCampaign(id); if (r.error) setMsg(r.error); else router.push("/admin/partners?tab=outreach"); }); }}>Delete campaign</button>
        )}
      </div>
      {msg && <p className="text-sm text-slate-300">{msg}</p>}
      <div className="flex flex-wrap items-center gap-2 text-sm">
        <input className="input h-9 w-64" placeholder="send a [TEST] copy to…" value={testTo} onChange={(e) => setTestTo(e.target.value)} />
        <button className="btn-secondary h-9 px-3" disabled={pending || !testTo}
          onClick={() => start(async () => { const r = await sendOutreachTestEmail({ campaignId: id, to: testTo }); setMsg("error" in r && r.error ? r.error : `Test sent to ${testTo}.`); })}>Send test</button>
        <span className="text-xs text-slate-500">Uses the sample recipient and a dead claim link — no invite is created.</span>
      </div>
      {editing && !closed && (
        <div className="rounded-xl border border-white/10 p-4">
          <SettingsFields s={s} set={(p) => setS((x) => ({ ...x, ...p }))} templates={templates} mailboxes={mailboxes} />
          <button className="btn-primary mt-3 h-9 px-4" disabled={pending}
