"use client";

import { useRouter } from "next/navigation";
import { useState, useTransition } from "react";
import { outreachItemAction, outreachRecipientTimeline, outreachSendNow, previewOutreachTemplate } from "@/lib/actions-outreach";
import { PreviewModal, type PreviewData } from "./PreviewModal";

export type RecipientRow = {
  id: string; email: string; fullName: string; game: string; channelUrl: string | null; country: string | null; subscribers: string | null;
  status: string; error: string | null; sentAt: string | null; templateName: string | null;
  opened: boolean; clicked: boolean; claimed: boolean; replied: boolean; bounced: boolean; unsubscribed: boolean;
};
const TONE: Record<string, string> = { QUEUED: "text-slate-300", SENDING: "text-amber-300", SENT: "text-emerald-400", FAILED: "text-red-400", SKIPPED: "text-slate-500" };

export function RecipientsTable({ rows, canEdit, campaignTemplateName }: { rows: RecipientRow[]; canEdit: boolean; campaignTemplateName: string }) {
  const router = useRouter();
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<string | null>(null);
  const [filter, setFilter] = useState("ALL");
  const [edit, setEdit] = useState<RecipientRow | null>(null);
  const [preview, setPreview] = useState<PreviewData | null>(null);
  const [timeline, setTimeline] = useState<{ email: string; rows: { at: string; kind: string; detail: string | null }[] } | null>(null);
  const shown = rows.filter((r) => filter === "ALL" || r.status === filter);
  const run = (fn: () => Promise<{ error?: string } | void>) => start(async () => { const r = await fn(); setMsg(r && "error" in r && r.error ? r.error : null); router.refresh(); });
  const count = (s: string) => rows.filter((r) => r.status === s).length;

  return (
    <div className="space-y-3">
      <div className="flex flex-wrap items-center gap-2 px-4 text-xs">
        {["ALL", "QUEUED", "SENT", "FAILED", "SKIPPED"].map((f) => (
          <button key={f} onClick={() => setFilter(f)} className={`rounded-full border px-3 py-1 ${filter === f ? "border-brand-400 text-white" : "border-white/10 text-slate-400"}`}>
            {f.toLowerCase()} {f === "ALL" ? rows.length : count(f)}
          </button>
        ))}
        {msg && <span className="text-red-400">{msg}</span>}
      </div>
      <div className="overflow-x-auto">
        <table className="table-shell min-w-[960px]">
          <thead><tr><th>Recipient</th><th>Context</th><th>Template</th><th>Status</th><th>Engagement</th><th></th></tr></thead>
          <tbody>
            {shown.map((r, idx) => (
              <tr key={r.id}>
                <td>
                  <div className="font-mono text-xs text-slate-200">{r.email}</div>
                  <div className="text-xs text-slate-500">{r.fullName}</div>
                </td>
                <td className="text-xs text-slate-400">{[r.game, r.country, r.subscribers && `${r.subscribers} subs`].filter(Boolean).join(" · ") || "—"}</td>
                <td className="text-xs text-slate-400">{r.templateName ?? campaignTemplateName}</td>
                <td className="text-xs">
                  <span className={TONE[r.status]}>{r.status.toLowerCase()}</span>
                  {r.sentAt && <div className="text-slate-500">{r.sentAt.slice(0, 16).replace("T", " ")}</div>}
                  {r.error && <div className="max-w-[240px] truncate text-red-300" title={r.error}>{r.error}</div>}
                </td>
                <td className="text-xs text-slate-400">
                  {[r.opened && "opened", r.clicked && "clicked", r.claimed && "claimed", r.replied && "replied", r.bounced && "bounced", r.unsubscribed && "unsubscribed"].filter(Boolean).join(" · ") || "—"}
                </td>
                <td className="text-right">
                  <span className="inline-flex flex-wrap justify-end gap-x-3 gap-y-1 text-xs font-semibold">
                    <button className="text-slate-300 hover:underline" disabled={pending} onClick={() => run(async () => { const p = await previewOutreachTemplate({ itemId: r.id, campaignId: undefined }); void p; })} hidden />
                    <button className="text-slate-300 hover:underline" disabled={pending} onClick={() => start(async () => { const p = await previewOutreachTemplate({ itemId: r.id, campaignId: campaignIdOf(rows) }); if ("error" in p && p.error) setMsg(p.error); else setPreview(p as PreviewData); })}>Preview</button>
                    <button className="text-slate-300 hover:underline" disabled={pending} onClick={() => start(async () => { const t = await outreachRecipientTimeline(r.email); setTimeline({ email: r.email, rows: t.rows }); })}>Timeline</button>
                    {canEdit && r.status === "QUEUED" && (
                      <>
                        <button className="text-slate-300 hover:underline" disabled={pending || idx === 0} onClick={() => run(() => outreachItemAction(r.id, "up"))}>↑</button>
                        <button className="text-slate-300 hover:underline" disabled={pending} onClick={() => run(() => outreachItemAction(r.id, "down"))}>↓</button>
                        <button className="text-slate-300 hover:underline" disabled={pending} onClick={() => run(() => outreachItemAction(r.id, "top"))}>Top</button>
                      </>
                    )}
                    {canEdit && (r.status === "QUEUED" || r.status === "FAILED" || r.status === "SKIPPED") && <button className="text-slate-300 hover:underline" disabled={pending} onClick={() => setEdit(r)}>Edit</button>}
