"use client";

import { useRouter } from "next/navigation";
import { useEffect, useRef, useState, useTransition } from "react";
import { archiveOutreachTemplate, duplicateOutreachTemplate, previewOutreachTemplate, saveOutreachTemplate, sendOutreachTestEmail } from "@/lib/actions-outreach";
import { TEMPLATE_VARIABLES } from "@/lib/outreach/render";

type Prev = { subject: string; html: string; text: string; warn?: string | null; sender?: string } | { error: string };

/** Template editor with a live preview rendered by the SAME renderer the send uses, using a sample recipient. */
export function TemplateEditor({ id, name: n0, subject: s0, body: b0, kind, builtIn, archived }: {
  id?: string; name: string; subject: string; body: string; kind: string; builtIn: boolean; archived: boolean;
}) {
  const router = useRouter();
  const [name, setName] = useState(n0);
  const [subject, setSubject] = useState(s0);
  const [body, setBody] = useState(b0);
  const [prev, setPrev] = useState<Prev | null>(null);
  const [msg, setMsg] = useState<string | null>(null);
  const [testTo, setTestTo] = useState("");
  const [pending, start] = useTransition();
  const ta = useRef<HTMLTextAreaElement>(null);
  const readOnly = builtIn || kind === "CODE";

  useEffect(() => {
    const t = setTimeout(async () => {
      if (!id && !body.trim()) { setPrev(null); return; }
      // Drafts preview unsaved text; a saved template previews through the same path.
      const r = id ? await previewOutreachTemplate({ templateId: id, subject, body: kind === "CODE" ? undefined : body }) : await previewOutreachTemplate({ templateId: undefined, subject, body });
      setPrev(r as Prev);
    }, 400);
    return () => clearTimeout(t);
  }, [id, subject, body, kind]);

  function insert(v: string) {
    const el = ta.current;
    if (!el) return setBody((b) => `${b}{{${v}}}`);
    const { selectionStart: a, selectionEnd: z } = el;
    setBody(body.slice(0, a) + `{{${v}}}` + body.slice(z));
    requestAnimationFrame(() => { el.focus(); el.selectionStart = el.selectionEnd = a + v.length + 4; });
  }

  return (
    <div className="grid gap-4 lg:grid-cols-2">
      <div className="space-y-3 text-sm">
        {readOnly && <p className="rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-amber-200">{kind === "CODE" ? "This template is rendered by code and can't be edited here." : "Built-in templates are read-only."} Duplicate it to make your own version.</p>}
        <label className="block"><span className="label">Template name</span><input className="input w-full" value={name} disabled={readOnly} onChange={(e) => setName(e.target.value)} /></label>
        <label className="block"><span className="label">Subject</span><input className="input w-full" value={subject} disabled={readOnly} onChange={(e) => setSubject(e.target.value)} /></label>
        {kind !== "CODE" && (
          <>
            <label className="block"><span className="label">Body</span>
              <textarea ref={ta} rows={20} className="input w-full font-mono text-xs leading-relaxed" value={body} disabled={readOnly} onChange={(e) => setBody(e.target.value)} />
            </label>
            {!readOnly && (
              <div className="flex flex-wrap gap-1.5">
                {TEMPLATE_VARIABLES.map((v) => <button key={v} type="button" onClick={() => insert(v)} className="rounded-md border border-white/10 px-2 py-0.5 font-mono text-[11px] text-slate-300 hover:bg-white/10">{`{{${v}}}`}</button>)}
              </div>
            )}
            <details className="text-xs text-slate-400">
              <summary className="cursor-pointer">Formatting help</summary>
              <ul className="mt-1 list-disc space-y-0.5 pl-5">
                <li>Blank line = new paragraph; a single line break stays a line break.</li>
                <li>Lines starting with <code>- </code> make a bullet list.</li>
                <li><code>**bold**</code> and <code>[link text](https://example.com)</code> work inline.</li>
                <li><code>[[button: Claim your invite | {"{{claimUrl}}"}]]</code> on its own line makes a button.</li>
                <li>Your signature and the unsubscribe + postal-address footer are added automatically to every email and can&apos;t be removed.</li>
              </ul>
            </details>
          </>
        )}
        {msg && <p className={msg.startsWith("Saved") || msg.startsWith("Test sent") ? "text-emerald-400" : "text-red-400"}>{msg}</p>}
        <div className="flex flex-wrap items-center gap-2">
          {!readOnly && <button className="btn-primary h-9 px-4" disabled={pending} onClick={() => start(async () => {
            const r = await saveOutreachTemplate({ id, name, subject, body });
            if (r.error) setMsg(r.error); else { setMsg("Saved."); if (!id && r.id) router.push(`/admin/partners/outreach/templates/${r.id}`); else router.refresh(); }
          })}>Save template</button>}
          {id && <button className="btn-secondary h-9 px-4" disabled={pending} onClick={() => start(async () => { const r = await duplicateOutreachTemplate(id); if (r.error) setMsg(r.error); else if (r.id) router.push(`/admin/partners/outreach/templates/${r.id}`); })}>Duplicate</button>}
          {id && !builtIn && <button className="btn-secondary h-9 px-4" disabled={pending} onClick={() => start(async () => { const r = await archiveOutreachTemplate(id, !archived); if (r.error) setMsg(r.error); else router.refresh(); })}>{archived ? "Unarchive" : "Archive"}</button>}
        </div>
        {id && (
          <div className="flex flex-wrap items-center gap-2">
            <input className="input h-9 w-64" placeholder="send a [TEST] copy to…" value={testTo} onChange={(e) => setTestTo(e.target.value)} />
            <button className="btn-secondary h-9 px-3" disabled={pending || !testTo} onClick={() => start(async () => { const r = await sendOutreachTestEmail({ templateId: id, subject, body: kind === "CODE" ? undefined : body, to: testTo }); setMsg("error" in r && r.error ? r.error : `Test sent to ${testTo}.`); })}>Send test</button>
          </div>
        )}
      </div>
      <div className="space-y-2">
        <p className="section-label">Live preview — sample recipient (Alex Morgan · Valheim)</p>
        {prev && "error" in prev ? <p className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">{prev.error}</p> : prev ? (
          <>
            {prev.warn && <p className="text-xs text-amber-300">{prev.warn}</p>}
            <p className="text-sm"><span className="text-slate-500">Subject:</span> <span className="text-slate-100">{prev.subject}</span></p>
            <iframe title="Template preview" srcDoc={prev.html} sandbox="" className="h-[620px] w-full rounded-lg border border-white/10 bg-white" />
            <details className="text-xs text-slate-400"><summary className="cursor-pointer">Plain-text version (auto-generated)</summary><pre className="mt-1 max-h-48 overflow-auto whitespace-pre-wrap font-mono text-[11px]">{prev.text}</pre></details>
          </>
        ) : <p className="text-sm text-slate-500">Start typing to see the preview.</p>}
      </div>
    </div>
  );
}
