"use client";

import { useRouter } from "next/navigation";
import { useState, useTransition } from "react";
import { addOutreachSuppression, removeOutreachSuppression, scanOutreachInboxNow } from "@/lib/actions-outreach";

export function SuppressionPanel({ rows, senders }: { rows: { id: string; email: string; reason: string; source: string | null; createdAt: string }[]; senders: string[] }) {
  const router = useRouter();
  const [email, setEmail] = useState("");
  const [msg, setMsg] = useState<string | null>(null);
  const [pending, start] = useTransition();
  return (
    <div className="space-y-3 text-sm">
      <div className="flex flex-wrap items-center gap-2">
        <input className="input h-9 w-64" placeholder="address to never email" value={email} onChange={(e) => setEmail(e.target.value)} />
        <button className="btn-secondary h-9 px-3" disabled={pending || !email} onClick={() => start(async () => { const r = await addOutreachSuppression(email); setMsg(r.error ?? "Added."); setEmail(""); router.refresh(); })}>Suppress</button>
        {senders.map((s) => (
          <button key={s} className="btn-secondary h-9 px-3" disabled={pending} onClick={() => start(async () => { const r = await scanOutreachInboxNow(s); setMsg("error" in r && r.error ? r.error : `Scanned ${s}: ${(r as { replies: number }).replies} replies, ${(r as { bounces: number }).bounces} bounces, ${(r as { unsubscribes: number }).unsubscribes} unsubscribes.`); router.refresh(); })}>Scan {s} inbox now</button>
        ))}
      </div>
      <p className="text-xs text-slate-500">The scan is read-only (it never marks, moves or deletes mail) and also runs automatically every 10 minutes. Unsubscribe-link clicks, &quot;unsubscribe&quot; replies and bounces land here automatically.</p>
      {msg && <p className="text-slate-300">{msg}</p>}
      <div className="max-h-72 overflow-auto">
        <table className="table-shell min-w-[560px]">
          <thead><tr><th>Address</th><th>Why</th><th>Source</th><th>When</th><th></th></tr></thead>
          <tbody>
            {rows.map((r) => (
              <tr key={r.id}>
                <td className="font-mono text-xs">{r.email}</td><td className="text-xs text-slate-300">{r.reason.toLowerCase()}</td>
                <td className="text-xs text-slate-500">{r.source ?? "—"}</td><td className="text-xs text-slate-500">{r.createdAt.slice(0, 10)}</td>
                <td className="text-right"><button className="text-xs text-red-400 hover:underline" disabled={pending} onClick={() => { if (confirm(`Allow emailing ${r.email} again?`)) start(async () => { await removeOutreachSuppression(r.id); router.refresh(); }); }}>Remove</button></td>
