import Link from "next/link";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { PageHeader, Badge } from "@/components/ui/primitives";
import { campaignStats } from "@/lib/outreach/campaign-core";
import { canEditRecipients } from "@/lib/outreach/state";
import { effectiveDailyCap, localDayKey, canSendNow } from "@/lib/outreach/pacing";
import { pacingOf } from "@/lib/outreach/campaign-core";
import { getSettingBool } from "@/lib/settings";
import { CampaignControls, KillSwitch, type CampaignSettings } from "@/components/admin/outreach/CampaignForms";
import { CsvImport } from "@/components/admin/outreach/CsvImport";
import { RecipientsTable, type RecipientRow } from "@/components/admin/outreach/RecipientsTable";

export const dynamic = "force-dynamic";
const TONE: Record<string, "slate" | "green" | "amber" | "brand" | "red"> = { DRAFT: "slate", RUNNING: "green", PAUSED: "amber", COMPLETED: "brand", CANCELLED: "red" };

export default async function CampaignPage({ params }: { params: Promise<{ id: string }> }) {
  await requireArea("billing");
  const { id } = await params;
  const c = await db.outreachCampaign.findUnique({ where: { id }, include: { template: true } });
  if (!c) notFound();
  const [templates, mailboxes, items, stats, killed] = await Promise.all([
    db.outreachTemplate.findMany({ orderBy: [{ builtIn: "desc" }, { name: "asc" }], select: { id: true, name: true, kind: true, status: true } }),
    db.companyMailbox.findMany({ where: { status: "ACTIVE" }, select: { address: true }, orderBy: { address: "asc" } }),
    db.outreachQueueItem.findMany({ where: { campaignId: id }, orderBy: [{ sortOrder: "asc" }, { createdAt: "asc" }], take: 2000 }),
    campaignStats(id),
    getSettingBool("outreach_paused_global", false),
  ]);
  const logIds = items.map((i) => i.emailLogId).filter((x): x is string => !!x);
  const sentEmails = items.filter((i) => i.status === "SENT").map((i) => i.email);
  const [logs, claims, evs] = await Promise.all([
    logIds.length ? db.emailLog.findMany({ where: { id: { in: logIds } }, select: { id: true, openedAt: true, clickedAt: true } }) : [],
    sentEmails.length ? db.partnerInvite.findMany({ where: { kind: "CREATOR", email: { in: sentEmails }, acceptedAt: { not: null } }, select: { email: true } }) : [],
    db.outreachEvent.findMany({ where: { campaignId: id, kind: { in: ["REPLY", "BOUNCE", "UNSUBSCRIBE"] } }, select: { kind: true, email: true } }),
  ]);
  const logMap = new Map(logs.map((l) => [l.id, l]));
  const claimed = new Set(claims.map((x) => x.email.toLowerCase()));
  const ev = (k: string) => new Set(evs.filter((e) => e.kind === k).map((e) => e.email));
  const replied = ev("REPLY"), bounced = ev("BOUNCE"), unsub = ev("UNSUBSCRIBE");
  const rows: RecipientRow[] = items.map((i) => ({
    id: i.id, email: i.email, fullName: i.fullName, game: i.game, channelUrl: i.channelUrl, country: i.country, subscribers: i.subscribers,
    status: i.status, error: i.error, sentAt: i.sentAt?.toISOString() ?? null, templateName: i.templateName,
    opened: !!(i.emailLogId && logMap.get(i.emailLogId)?.openedAt), clicked: !!(i.emailLogId && logMap.get(i.emailLogId)?.clickedAt),
    claimed: claimed.has(i.email.toLowerCase()), replied: replied.has(i.email), bounced: bounced.has(i.email), unsubscribed: unsub.has(i.email),
  }));
  const settings: CampaignSettings = {
    id: c.id, name: c.name, templateId: c.templateId ?? "", senderAddress: c.senderAddress, subjectOverride: c.subjectOverride ?? "", bodyOverride: c.bodyOverride ?? "",
    intervalSeconds: c.intervalSeconds, jitterPct: c.jitterPct, windowStartHour: c.windowStartHour, windowEndHour: c.windowEndHour,
    timezone: c.timezone, days: c.days, dailyCap: c.dailyCap, warmupEnabled: c.warmupEnabled, warmupStartCap: c.warmupStartCap, warmupStep: c.warmupStep,
  };
  const now = new Date();
  const sentToday = items.filter((i) => i.sentAt && localDayKey(i.sentAt, c.timezone) === localDayKey(now, c.timezone)).length;
  const cap = effectiveDailyCap(pacingOf(c), c.startedAt, now);
  const decision = c.status === "RUNNING" ? canSendNow(pacingOf(c), { nextSendAt: c.nextSendAt, startedAt: c.startedAt, sentToday }, now) : null;

  const cards: [string, number, string?][] = [
    ["Queued", stats.queued], ["Sent", stats.sent, "text-emerald-400"], ["Failed", stats.failed, stats.failed ? "text-red-400" : ""], ["Skipped", stats.skipped],
    ["Opened*", stats.opened], ["Clicked", stats.clicked], ["Claimed", stats.claimed, "text-emerald-400"], ["Replied", stats.replied], ["Bounced", stats.bounced, stats.bounced ? "text-red-400" : ""], ["Unsubscribed", stats.unsubscribed],
  ];
  return (
    <div className="space-y-6">
      <PageHeader title={c.name} sub={`Template: ${c.template?.name ?? "—"} · sender ${c.senderAddress}`} />
      <p className="text-sm"><Link href="/admin/partners?tab=outreach" className="text-brand-300 hover:underline">← All campaigns</Link></p>
      {killed && <KillSwitch on />}
      <div className="card space-y-4">
        <div className="flex flex-wrap items-center gap-3">
          <Badge tone={TONE[c.status] ?? "slate"}>{c.status.toLowerCase()}</Badge>
          <span className="text-sm text-slate-400">
            every {c.intervalSeconds}s{c.jitterPct ? ` ±${c.jitterPct}%` : ""}
            {c.windowStartHour != null ? ` · ${c.windowStartHour}:00–${c.windowEndHour}:00 ${c.timezone}` : ""}
            {cap != null ? ` · today ${sentToday}/${cap}` : ` · today ${sentToday}`}
          </span>
          {decision && !decision.ok && <span className="text-xs text-amber-300">waiting: {decision.reason.replace("-", " ")}{decision.retryAt ? ` until ${decision.retryAt.toISOString().slice(0, 16).replace("T", " ")} UTC` : ""}</span>}
        </div>
        <CampaignControls id={c.id} status={c.status} settings={settings} templates={templates.map((t) => ({ id: t.id, name: t.name, kind: t.kind, archived: t.status === "ARCHIVED" }))} mailboxes={mailboxes.map((m) => m.address)} hasQueued={stats.queued > 0} pauseReason={c.pauseReason} isLegacy={c.isLegacyDefault} />
      </div>
      <div className="card">
        <dl className="grid grid-cols-2 gap-4 sm:grid-cols-5">
          {cards.map(([l, v, t]) => <div key={l}><dt className="text-xs text-slate-500">{l}</dt><dd className={`text-2xl font-bold ${t ?? ""}`}>{v}</dd></div>)}
        </dl>
        <p className="mt-3 text-xs text-slate-500">*Opens are approximate — mail apps that pre-load images (e.g. Apple Mail) count as opens, and clients that block images hide real ones. Claimed comes from the invite itself. Replied/bounced come from the read-only inbox scan.</p>
      </div>
      {canEditRecipients(c.status) && (
        <div className="card space-y-3"><p className="section-label">Add recipients from a CSV</p><CsvImport campaignId={c.id} /></div>
      )}
      <div className="card overflow-hidden p-0">
        <div className="px-4 pt-4"><p className="section-label">Recipients</p></div>
        <RecipientsTable rows={rows} canEdit={canEditRecipients(c.status)} campaignTemplateName={c.template?.name ?? "—"} campaignId={c.id} />
      </div>
    </div>
  );
}
