import Link from "next/link";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { PageHeader } from "@/components/ui/primitives";
import { ensureBuiltInTemplates } from "@/lib/outreach/service";
import { TemplateEditor } from "@/components/admin/outreach/TemplateEditor";

export const dynamic = "force-dynamic";

export default async function TemplatePage({ params }: { params: Promise<{ id: string }> }) {
  await requireArea("billing");
  const { id } = await params;
  await ensureBuiltInTemplates();
  if (id === "new") {
    return (
      <div className="space-y-6">
        <PageHeader title="New outreach template" sub="Write the email once, reuse it across campaigns. Variables are filled per recipient." />
        <p className="text-sm"><Link href="/admin/partners?tab=outreach" className="text-brand-300 hover:underline">← Outreach</Link></p>
        <div className="card"><TemplateEditor name="" subject="{{firstName}}, a quick idea for your {{game}} channel" body={"Hey {{firstName}},\n\n\n\n[[button: Claim your invite | {{claimUrl}}]]"} kind="MARKDOWN" builtIn={false} archived={false} /></div>
      </div>
    );
  }
  const t = await db.outreachTemplate.findUnique({ where: { id } });
  if (!t) notFound();
  const used = await db.outreachCampaign.count({ where: { templateId: t.id } });
  return (
    <div className="space-y-6">
      <PageHeader title={t.name} sub={`${t.builtIn ? "Built-in · read-only · " : ""}${t.status === "ARCHIVED" ? "archived · " : ""}used by ${used} campaign${used === 1 ? "" : "s"}`} />
      <p className="text-sm"><Link href="/admin/partners?tab=outreach" className="text-brand-300 hover:underline">← Outreach</Link></p>
      <div className="card"><TemplateEditor id={t.id} name={t.name} subject={t.subject} body={t.body} kind={t.kind} builtIn={t.builtIn} archived={t.status === "ARCHIVED"} /></div>
    </div>
  );
}
