import Link from "next/link";
import { db } from "@/lib/db";
import { Badge, timeAgo } from "@/components/ui/primitives";
import { getSettingBool } from "@/lib/settings";
import { adoptLegacyQueue, KILL_SWITCH_KEY } from "@/lib/outreach/campaign-core";
import { ensureBuiltInTemplates } from "@/lib/outreach/service";
import { KillSwitch, NewCampaignForm } from "@/components/admin/outreach/CampaignForms";
import { SuppressionPanel } from "@/components/admin/outreach/SuppressionPanel";

const TONE: Record<string, "slate" | "green" | "amber" | "brand" | "red"> = { DRAFT: "slate", RUNNING: "green", PAUSED: "amber", COMPLETED: "brand", CANCELLED: "red" };

/** The Outreach tab: kill switch, campaigns, templates, suppression list. */
export async function OutreachTab() {
  await ensureBuiltInTemplates();
  await adoptLegacyQueue(); // idempotent — folds the pre-campaign CSV queue into the default campaign
  const [killed, campaigns, templates, mailboxes, suppressed, grouped] = await Promise.all([
    getSettingBool(KILL_SWITCH_KEY, false),
    db.outreachCampaign.findMany({ orderBy: { createdAt: "desc" }, include: { template: { select: { name: true } } } }),
    db.outreachTemplate.findMany({ orderBy: [{ builtIn: "desc" }, { createdAt: "desc" }], include: { _count: { select: { campaigns: true } } } }),
    db.companyMailbox.findMany({ where: { status: "ACTIVE" }, select: { address: true }, orderBy: { address: "asc" } }),
    db.outreachSuppression.findMany({ orderBy: { createdAt: "desc" }, take: 200 }),
    db.outreachQueueItem.groupBy({ by: ["campaignId", "status"], _count: { _all: true } }),
  ]);
  const n = (cid: string, st: string) => grouped.find((g) => g.campaignId === cid && g.status === st)?._count._all ?? 0;
  const senders = [...new Set(campaigns.map((c) => c.senderAddress))];

  return (
    <div className="space-y-6">
      <KillSwitch on={killed} />

      <div className="card overflow-x-auto p-0">
        <div className="px-4 pt-4">
          <p className="section-label">Campaigns</p>
          <p className="mt-1 text-xs text-slate-500">A campaign = recipient list + template + sender + pacing. Open one to upload a CSV, preview, start, pause or retry.</p>
        </div>
        {campaigns.length === 0 ? <p className="px-4 py-8 text-sm text-slate-400">No campaigns yet.</p> : (
          <table className="table-shell mt-2 min-w-[860px]">
            <thead><tr><th>Campaign</th><th>Template</th><th>Status</th><th className="text-right">Queued</th><th className="text-right">Sent</th><th className="text-right">Failed</th><th>Pacing</th><th>Created</th></tr></thead>
            <tbody>
              {campaigns.map((c) => (
                <tr key={c.id}>
                  <td><Link href={`/admin/partners/outreach/${c.id}`} className="text-brand-300 hover:underline">{c.name}</Link><div className="text-xs text-slate-500">{c.senderAddress}</div></td>
                  <td className="text-xs text-slate-300">{c.template?.name ?? "—"}</td>
                  <td><Badge tone={TONE[c.status] ?? "slate"}>{c.status.toLowerCase()}</Badge>{c.pauseReason && <div className="max-w-[200px] text-xs text-amber-300">{c.pauseReason}</div>}</td>
                  <td className="text-right font-mono">{n(c.id, "QUEUED")}</td>
                  <td className="text-right font-mono text-emerald-400">{n(c.id, "SENT")}</td>
                  <td className="text-right font-mono text-red-400">{n(c.id, "FAILED")}</td>
                  <td className="text-xs text-slate-400">{c.intervalSeconds}s{c.jitterPct ? ` ±${c.jitterPct}%` : ""}{c.dailyCap ? ` · ${c.dailyCap}/day` : ""}</td>
                  <td className="text-xs text-slate-500">{timeAgo(c.createdAt)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      <div className="card space-y-3">
        <p className="section-label">New campaign</p>
        <NewCampaignForm templates={templates.map((t) => ({ id: t.id, name: t.name, kind: t.kind, archived: t.status === "ARCHIVED" }))} mailboxes={mailboxes.map((m) => m.address)} />
      </div>

      <div className="card overflow-x-auto p-0">
        <div className="flex items-center justify-between px-4 pt-4">
          <p className="section-label">Templates</p>
          <Link href="/admin/partners/outreach/templates/new" className="btn-secondary h-8 px-3 text-xs">New template</Link>
        </div>
        <table className="table-shell mt-2 min-w-[640px]">
          <thead><tr><th>Name</th><th>Kind</th><th>Subject</th><th className="text-right">Campaigns</th><th>Status</th></tr></thead>
          <tbody>
            {templates.map((t) => (
              <tr key={t.id}>
                <td><Link href={`/admin/partners/outreach/templates/${t.id}`} className="text-brand-300 hover:underline">{t.name}</Link></td>
                <td className="text-xs text-slate-400">{t.builtIn ? "built-in" : "custom"}{t.kind === "CODE" ? " · code" : ""}</td>
                <td className="max-w-[320px] truncate text-xs text-slate-400">{t.subject}</td>
                <td className="text-right font-mono">{t._count.campaigns}</td>
                <td><Badge tone={t.status === "ACTIVE" ? "green" : "slate"}>{t.status.toLowerCase()}</Badge></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="card space-y-3">
        <p className="section-label">Suppression list &amp; inbox</p>
        <SuppressionPanel senders={senders} rows={suppressed.map((s) => ({ id: s.id, email: s.email, reason: s.reason, source: s.source, createdAt: s.createdAt.toISOString() }))} />
      </div>
    </div>
  );
}
