/**
 * Integration self-test for the outreach campaign engine against a THROWAWAY
 * database. Refuses to run unless DATABASE_URL names a `nxeon_agt_*` database.
 * SMTP is nodemailer's jsonTransport (nothing leaves the process), IMAP is a
 * fixture fetcher, the clock is injected.
 *
 *   DATABASE_URL=postgresql://…/nxeon_agt_x AUTH_SECRET=x NXEON_SANDBOX=1 \
 *     npx tsx scripts/outreach-engine-selftest.ts
 */
import assert from "node:assert/strict";
import nodemailer from "nodemailer";

const url = process.env.DATABASE_URL ?? "";
if (!/nxeon_agt_/.test(url)) { console.error("refusing: DATABASE_URL must be a throwaway nxeon_agt_* database"); process.exit(2); }
process.env.NXEON_SANDBOX = "1";
process.env.AUTH_SECRET ||= "selftest-secret";
process.env.APP_URL ||= "http://localhost:3110";

async function main() {
  const { db } = await import("../lib/db");
  const { encryptSecret } = await import("../lib/crypto-box");
  const core = await import("../lib/outreach/campaign-core");
  const svc = await import("../lib/outreach/service");
  const { scanOutreachInbox } = await import("../lib/outreach/inbox-scan");
  const { setSetting } = await import("../lib/settings");

  // --- fixtures
  await db.companyMailbox.upsert({
    where: { address: "santino@nxeon.cloud" }, update: {},
    create: { address: "santino@nxeon.cloud", passwordEnc: encryptSecret("x"), displayName: "Santino", signatureHtml: "<b>Santino</b>", signature: "Santino" },
  });
  if (!(await db.brand.findFirst({ where: { name: "Nxeon" } }))) await db.brand.create({ data: { name: "Nxeon", physicalPostalAddress: "1 Test St, Toronto ON" } });
  await setSetting(core.KILL_SWITCH_KEY, "false");
  const sent: { to: string; subject: string; html: string; headers: string }[] = [];
  const transport = () => ({
    sendMail: async (m: { envelope: { to: string[] }; raw: Buffer }) => {
      const raw = m.raw.toString();
      sent.push({ to: m.envelope.to[0], subject: /^Subject: (.*)$/m.exec(raw)?.[1] ?? "", html: raw, headers: raw });
      return { messageId: `<t${sent.length}@test>` };
    },
  }) as unknown as nodemailer.Transporter;

  // --- 1. legacy queue adoption (the live 97-row queue): orphans, no campaign
  await db.outreachQueueItem.deleteMany({});
  await db.outreachCampaign.deleteMany({});
  for (let i = 0; i < 3; i++) await db.outreachQueueItem.create({ data: { email: `legacy${i}@example.com`, fullName: `Legacy ${i}`, game: "Rust" } });
  await db.outreachQueueItem.create({ data: { email: "done@example.com", fullName: "Done", game: "Rust", status: "SENT", sentAt: new Date() } });
  const ad = await core.adoptLegacyQueue();
  assert.equal(ad.adopted, 4);
  const legacy = await db.outreachCampaign.findFirstOrThrow({ where: { isLegacyDefault: true } });
  assert.equal(legacy.status, "RUNNING");
  assert.equal(await db.outreachQueueItem.count({ where: { campaignId: null } }), 0);
  assert.equal((await core.adoptLegacyQueue()).adopted, 0, "idempotent");
  console.log("ok 1 legacy adoption");

